/**
 * dsh-provider-usage — 报告重试状态账本（#1010 B1）。
 *
 * retry-ledger.json 是自动重试成本与预算的事实源：每次状态变化都在 per-root
 * Promise 临界区内读-改-写，并以 0600 临时文件 → fsync → atomic rename →
 * 目录 fsync 提交。损坏文件先 no-clobber 取证隔离并留下 fail-closed 标记；
 * 任何后续调用都不会把已被隔离的缺失文件误判成空账本。
 */

import { constants, existsSync } from "node:fs";
import {
  chmod,
  copyFile,
  link,
  mkdir,
  open,
  readFile,
  readdir,
  rename,
  unlink,
} from "node:fs/promises";
import { randomUUID } from "node:crypto";
import { dirname, join, resolve } from "node:path";
import type { ReportPeriod } from "../config/interface.ts";
import {
  beginAttempt as policyBeginAttempt,
  beginForce as policyBeginForce,
  createInitialEntry,
  recordFailure as policyRecordFailure,
  recover as policyRecover,
  shouldReconcileRetry,
  addRetryObservation,
  statusAgreesWithResult,
  usageFromRetryObservations,
  RETRY_MAX_ATTEMPTS,
  type RetryAttemptObservation,
  type RetryAttemptTokens,
  type RetryClaim,
  type RetryEntry,
  type RetryFailure,
  type RetryFailureKind,
  type RetryIndexKey,
  type RetryPhase,
  type RetryRouteSnapshot,
  type RetrySeed,
  type RetryTerminalReason,
  type RetryUsageTotals,
  emptyRetryAttemptTokens,
  emptyRetryUsage,
} from "./retry-policy.ts";

export const RETRY_LEDGER_SCHEMA = 1 as const;

const PERIODS = ["daily", "weekly", "monthly"] as const;
const PERIOD_SET: ReadonlySet<string> = new Set<ReportPeriod>(PERIODS);
const PHASES: ReadonlySet<string> = new Set<RetryPhase>([
  "initial",
  "waiting",
  "in-flight",
  "terminal",
]);

/** period 键收窄（类型谓词，取代 PERIODS.includes(x as ReportPeriod) 的断言逃逸）。 */
function isReportPeriod(value: string): value is ReportPeriod {
  return PERIOD_SET.has(value);
}

/** 生命周期相位收窄（类型谓词）。 */
function isRetryPhase(value: unknown): value is RetryPhase {
  return typeof value === "string" && PHASES.has(value);
}

/** 已登记尝试次数收窄：0..RETRY_MAX_ATTEMPTS 的整数。 */
function isRetryAttemptCounter(value: unknown): value is number {
  return (
    typeof value === "number" &&
    Number.isInteger(value) &&
    value >= 0 &&
    value <= RETRY_MAX_ATTEMPTS
  );
}

/** 下次重试时刻收窄：null（不排期）或非负安全整数。 */
function isRetryNextRetryAt(value: unknown): value is number | null {
  return value === null || isFiniteTimestamp(value);
}
const FAILURE_KINDS = new Set<RetryFailureKind>([
  "transient",
  "empty-output",
  "permanent",
  "aborted",
  "unknown",
  "storage",
]);
const CORRUPT_BACKUP_LIMIT = 5;
const STABLE_CODE_RE = /^[a-z0-9][a-z0-9._:-]{0,63}$/;
const CYCLE_ID_RE = /^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$/;

type RetryRecords = Partial<Record<ReportPeriod, Record<string, RetryEntry>>>;

interface RetryLedgerDocument {
  schema: typeof RETRY_LEDGER_SCHEMA;
  records: RetryRecords;
  /**
   * 已从可见 records 裁剪的 terminal key 墓碑（period → key → 终态 code）。
   * 墓碑必须全量保留，不得让「曾终态失败」的 key 静默重开新 cycle：
   * beginAttempt 命中墓碑即拒绝，只有 beginForce（手动强制）才开新 cycle。
   * 空表不落盘字段，兼容既有 schema:1 文档。
   */
  terminalKeys?: Partial<Record<ReportPeriod, Record<string, string>>>;
}

export interface RetryAttemptInput extends RetrySeed {
  cycleId?: string;
}

export interface RetryLedgerOptions {
  now?: () => number;
  createCycleId?: () => string;
  renameFile?: (from: string, to: string) => Promise<void>;
}

export type RetryLedgerErrorCode = "retry-ledger-corrupt" | "retry-ledger-storage";

export class RetryLedgerError extends Error {
  readonly code: RetryLedgerErrorCode;

  constructor(code: RetryLedgerErrorCode, message: string) {
    super(message);
    this.name = "RetryLedgerError";
    this.code = code;
  }
}

export interface RetryLedgerPort {
  list(): Promise<RetryEntry[]>;
  listDue(now: number, lastRun: Partial<Record<ReportPeriod, string>>): Promise<RetryEntry[]>;
  get(period: ReportPeriod, key: string): Promise<RetryEntry | undefined>;
  beginAttempt(input: RetryAttemptInput, now?: number): Promise<RetryClaim | null>;
  beginForce(input: RetrySeed, now?: number): Promise<RetryEntry>;
  recordAttempt(
    claim: RetryClaim,
    observation: RetryAttemptObservation,
    now?: number,
  ): Promise<RetryClaim | null>;
  recordFailure(claim: RetryClaim, failure: RetryFailure, now?: number): Promise<RetryEntry | null>;
  /** keep 中的 cycle 保持原 phase（storage-terminal fail-closed），不回落 waiting。 */
  recover(now?: number, keep?: readonly RetryIndexKey[]): Promise<RetryEntry[]>;
  clear(claim: RetryClaim): Promise<boolean>;
  reconcile(
    lastRun: Partial<Record<ReportPeriod, string>>,
    indexed: readonly RetryIndexKey[],
  ): Promise<RetryEntry[]>;
}

interface BackupEntry {
  name: string;
  timestamp: number;
  suffix: number;
}

const ledgerChains = new Map<string, Promise<void>>();

export function retryLedgerFile(root: string): string {
  return join(root, "reports", "retry-ledger.json");
}

function errorCode(error: unknown): string | undefined {
  if (typeof error !== "object" || error === null) return undefined;
  const code = (error as { code?: unknown }).code;
  return typeof code === "string" ? code : undefined;
}

function storageError(): RetryLedgerError {
  return new RetryLedgerError("retry-ledger-storage", "retry ledger storage operation failed");
}

function corruptError(): RetryLedgerError {
  return new RetryLedgerError(
    "retry-ledger-corrupt",
    "retry ledger is quarantined; manual recovery is required",
  );
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function hasExactKeys(value: Record<string, unknown>, keys: readonly string[]): boolean {
  const actual = Object.keys(value).sort();
  const expected = [...keys].sort();
  return actual.length === expected.length && actual.every((key, index) => key === expected[index]);
}

function isStableCode(value: unknown): value is string {
  return typeof value === "string" && STABLE_CODE_RE.test(value);
}

function isFiniteTimestamp(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
}

function isDateKey(value: unknown): value is string {
  if (typeof value !== "string" || !/^(19|20|21)\d{2}-\d{2}-\d{2}$/.test(value)) return false;
  const [yearText, monthText, dayText] = value.split("-");
  const year = Number(yearText);
  const month = Number(monthText);
  const day = Number(dayText);
  const date = new Date(Date.UTC(year, month - 1, day));
  return (
    date.getUTCFullYear() === year && date.getUTCMonth() === month - 1 && date.getUTCDate() === day
  );
}

function isMonthKey(value: unknown): value is string {
  return typeof value === "string" && /^(19|20|21)\d{2}-(0[1-9]|1[0-2])$/.test(value);
}

function isValidWindow(period: ReportPeriod, entry: Record<string, unknown>): boolean {
  const { key, startDay, endDay } = entry;
  if (!isDateKey(startDay) || !isDateKey(endDay) || startDay > endDay) return false;
  if (period === "monthly") {
    return isMonthKey(key) && startDay.slice(0, 7) === key;
  }
  return isDateKey(key) && key === startDay;
}

function parseRoute(value: unknown): RetryRouteSnapshot | null {
  if (!isRecord(value)) return null;
  const allowed =
    value.reasoningEffort === undefined
      ? ["provider", "model"]
      : ["provider", "model", "reasoningEffort"];
  if (!hasExactKeys(value, allowed)) return null;
  if (typeof value.provider !== "string" || typeof value.model !== "string") return null;
  if (value.reasoningEffort !== undefined && typeof value.reasoningEffort !== "string") {
    return null;
  }
  return value.reasoningEffort === undefined
    ? { provider: value.provider, model: value.model }
    : {
        provider: value.provider,
        model: value.model,
        reasoningEffort: value.reasoningEffort,
      };
}

function parseReason(value: unknown): RetryTerminalReason | null {
  if (value === null) return null;
  if (!isRecord(value) || !hasExactKeys(value, ["code", "kind"])) return null;
  if (!isStableCode(value.code) || typeof value.kind !== "string") return null;
  if (!FAILURE_KINDS.has(value.kind as RetryFailureKind)) return null;
  return { code: value.code, kind: value.kind as RetryFailureKind };
}

function parseMetric(value: unknown): number | null | undefined {
  return value === null
    ? null
    : typeof value === "number" && Number.isFinite(value) && value >= 0
      ? value
      : undefined;
}

function parseAttemptTokens(value: unknown): RetryAttemptTokens | null {
  if (
    !isRecord(value) ||
    !hasExactKeys(value, [
      "inputTokens",
      "outputTokens",
      "reasoningTokens",
      "totalTokens",
      "cacheReadTokens",
      "cacheWriteTokens",
    ])
  ) {
    return null;
  }
  const parsed: RetryAttemptTokens = emptyRetryAttemptTokens();
  for (const key of [
    "inputTokens",
    "outputTokens",
    "reasoningTokens",
    "totalTokens",
    "cacheReadTokens",
    "cacheWriteTokens",
  ] as const) {
    const metric = parseMetric(value[key]);
    if (metric === undefined) return null;
    parsed[key] = metric;
  }
  return parsed;
}

function parseUsage(value: unknown): RetryUsageTotals | null {
  if (
    !isRecord(value) ||
    !hasExactKeys(value, [
      "inputTokens",
      "outputTokens",
      "reasoningTokens",
      "totalTokens",
      "cacheReadTokens",
      "cacheWriteTokens",
      "durationMs",
    ])
  ) {
    return null;
  }
  const tokens = parseAttemptTokens({
    inputTokens: value.inputTokens,
    outputTokens: value.outputTokens,
    reasoningTokens: value.reasoningTokens,
    totalTokens: value.totalTokens,
    cacheReadTokens: value.cacheReadTokens,
    cacheWriteTokens: value.cacheWriteTokens,
  });
  if (tokens === null) return null;
  const durationMs = parseMetric(value.durationMs);
  if (durationMs === undefined) return null;
  return { ...tokens, durationMs };
}

/** 单条 attempt 观测的精确键集合（读盘口径，缺键/多键即拒）。 */
const OBSERVATION_KEYS = ["attempt", "result", "code", "status", "durationMs", "tokens"] as const;

function isObservationResult(value: unknown): value is "success" | "failure" {
  return value === "success" || value === "failure";
}

function isObservationStatus(value: unknown): value is RetryAttemptObservation["status"] {
  return value === "success" || value === "retry" || value === "terminal" || value === "aborted";
}

/** code 收窄：null（无失败码）或稳定码形态。 */
function isObservationCode(value: unknown): value is string | null {
  return value === null || isStableCode(value);
}

/** attempt 收窄：≥1 的整数。 */
function isObservationAttempt(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value >= 1;
}

/** 观测标量字段收窄（类型谓词承担 narrowing，取代读盘路径的 as 逃逸）。 */
export function narrowObservationScalars(
  value: Record<string, unknown>,
): Pick<RetryAttemptObservation, "attempt" | "result" | "code" | "status"> | null {
  if (!isObservationAttempt(value.attempt)) return null;
  if (!isObservationResult(value.result)) return null;
  if (!isObservationStatus(value.status)) return null;
  if (!isObservationCode(value.code)) return null;
  return {
    attempt: value.attempt,
    result: value.result,
    code: value.code,
    status: value.status,
  };
}

/**
 * 观测跨字段一致性（result⇔code 必填性、result⇔status、status⇔attempt 上限）。
 * 与 retry-policy 的 requireObservationConsistency 同口径——读盘校验只判真假、
 * 不抛错（抛错面在写入口）。
 */
export function hasConsistentObservationOutcome(observation: RetryAttemptObservation): boolean {
  if (observation.result === "success" && observation.code !== null) return false;
  if (observation.result === "failure" && observation.code === null) return false;
  if (!statusAgreesWithResult(observation)) return false;
  if (observation.status === "retry" && observation.attempt > RETRY_MAX_ATTEMPTS) return false;
  return true;
}

export function parseObservation(value: unknown): RetryAttemptObservation | null {
  if (!isRecord(value) || !hasExactKeys(value, OBSERVATION_KEYS)) return null;
  const durationMs = parseMetric(value.durationMs);
  if (durationMs === undefined) return null;
  const tokens = parseAttemptTokens(value.tokens);
  if (tokens === null) return null;
  const scalars = narrowObservationScalars(value);
  if (scalars === null) return null;
  const observation: RetryAttemptObservation = { ...scalars, durationMs, tokens };
  return hasConsistentObservationOutcome(observation) ? observation : null;
}

/**
 * 观测序列连续性（纯函数）：第 i 项的 attempt 必须是 i+1（跳号/重号皆拒），
 * 任一项非法则整序列拒。
 */
export function collectSequentialObservations(
  raw: readonly unknown[],
): RetryAttemptObservation[] | null {
  const attemptObservations: RetryAttemptObservation[] = [];
  for (const [index, rawObservation] of raw.entries()) {
    const observation = parseObservation(rawObservation);
    if (observation === null || observation.attempt !== index + 1) return null;
    attemptObservations.push(observation);
  }
  return attemptObservations;
}

/**
 * usage 合计自洽（纯函数）：落盘 usage 必须等于按观测序列重算的结果——
 * 杜绝手改/半写账本里 usage 与观测互相矛盾的成本失真。
 */
export function usageMatchesObservations(
  usage: RetryUsageTotals,
  attemptObservations: readonly RetryAttemptObservation[],
): boolean {
  return sameUsage(usageFromRetryObservations(attemptObservations), usage);
}

function parseObservationCollection(
  value: Record<string, unknown>,
): { attemptObservations: RetryAttemptObservation[]; usage: RetryUsageTotals } | null {
  if (!Array.isArray(value.attemptObservations)) return null;
  const attemptObservations = collectSequentialObservations(value.attemptObservations);
  if (attemptObservations === null) return null;
  if (attemptObservations.length > RETRY_MAX_ATTEMPTS + 1) return null;
  const usage = parseUsage(value.usage);
  if (usage === null) return null;
  return usageMatchesObservations(usage, attemptObservations)
    ? { attemptObservations, usage }
    : null;
}

function observationCountMatchesState(
  phase: RetryPhase,
  attempts: number,
  observationCount: number,
): boolean {
  // B2 兼容路径允许尚未调用 recordAttempt 就完成状态转移；一旦存在事实，
  // 观测序列必须与自动重试计数严格对应。
  if (observationCount === 0) return true;
  if (phase === "initial") return false;
  if (phase === "waiting") return observationCount === attempts;
  if (phase === "in-flight") {
    return observationCount === attempts || observationCount === attempts + 1;
  }
  return observationCount === attempts + 1;
}

/** 终态条目形态：terminal 恒真、终态原因非空、不再排期。 */
export function isWellFormedTerminalState(
  value: Record<string, unknown>,
  reason: RetryTerminalReason | null,
): boolean {
  return value.terminal === true && reason !== null && value.nextRetryAt === null;
}

/**
 * 非终态条目不变量：terminal/reason 须同时为空；in-flight 不排期；
 * initial/waiting 必有有限 nextRetryAt；initial 必零尝试。
 */
export function isWellFormedLiveState(
  value: Record<string, unknown>,
  reason: RetryTerminalReason | null,
  phase: RetryPhase,
  attempts: number,
): boolean {
  if (value.terminal || reason !== null) return false;
  if (phase === "in-flight" && value.nextRetryAt !== null) return false;
  if ((phase === "initial" || phase === "waiting") && !isFiniteTimestamp(value.nextRetryAt)) {
    return false;
  }
  return phase !== "initial" || attempts === 0;
}

/** 条目状态机自洽（终态与非终态两套不变量，见上）。 */
export function parseEntryState(
  value: Record<string, unknown>,
  reason: RetryTerminalReason | null,
  phase: RetryPhase,
  attempts: number,
): boolean {
  if (phase === "terminal") return isWellFormedTerminalState(value, reason);
  return isWellFormedLiveState(value, reason, phase, attempts);
}

/** 无观测序列的历史条目键集合（schema:1 基线形态）。 */
const LEGACY_ENTRY_KEYS = [
  "period",
  "key",
  "startDay",
  "endDay",
  "route",
  "attempts",
  "maxAttempts",
  "nextRetryAt",
  "terminal",
  "reason",
  "cycleId",
  "phase",
] as const;

/** 观测载荷两键须同在同缺——只带其一的条目视为半写账本，拒。 */
export function hasExpectedEntryKeys(value: Record<string, unknown>): boolean {
  const hasObservations = Object.hasOwn(value, "attemptObservations");
  if (hasObservations !== Object.hasOwn(value, "usage")) return false;
  const expectedKeys = hasObservations
    ? [...LEGACY_ENTRY_KEYS, "attemptObservations", "usage"]
    : LEGACY_ENTRY_KEYS;
  return hasExactKeys(value, expectedKeys);
}

/** 条目身份面：period/key 对位 + 窗口合法 + 路由快照可解析。 */
export function parseEntryIdentity(
  value: Record<string, unknown>,
  period: ReportPeriod,
  key: string,
): { startDay: string; endDay: string; route: RetryRouteSnapshot } | null {
  if (value.period !== period || value.key !== key || !isValidWindow(period, value)) return null;
  const route = parseRoute(value.route);
  if (route === null) return null;
  return {
    startDay: value.startDay as string,
    endDay: value.endDay as string,
    route,
  };
}

interface NarrowedEntryFields {
  attempts: number;
  terminal: boolean;
  nextRetryAt: number | null;
  cycleId: string;
  phase: RetryPhase;
  reason: RetryTerminalReason | null;
}

/** 条目标量字段收窄：尝试计数、终态标记、排期时刻、cycleId、相位、终态原因。 */
export function narrowEntryFields(value: Record<string, unknown>): NarrowedEntryFields | null {
  if (value.maxAttempts !== RETRY_MAX_ATTEMPTS) return null;
  if (!isRetryAttemptCounter(value.attempts)) return null;
  if (typeof value.terminal !== "boolean") return null;
  if (typeof value.cycleId !== "string" || !CYCLE_ID_RE.test(value.cycleId)) return null;
  if (!isRetryPhase(value.phase)) return null;
  if (!isRetryNextRetryAt(value.nextRetryAt)) return null;
  const reason = parseReason(value.reason);
  if (reason === null && value.reason !== null) return null;
  return {
    attempts: value.attempts,
    terminal: value.terminal,
    nextRetryAt: value.nextRetryAt,
    cycleId: value.cycleId,
    phase: value.phase,
    reason,
  };
}

/** 观测载荷：缺两键（历史条目）视作零观测空载荷。 */
export function parseEntryPayload(
  value: Record<string, unknown>,
): { attemptObservations: RetryAttemptObservation[]; usage: RetryUsageTotals } | null {
  if (!Object.hasOwn(value, "attemptObservations")) {
    return { attemptObservations: [], usage: emptyRetryUsage() };
  }
  return parseObservationCollection(value);
}

/** 观测事实与状态机自洽（观测条数对应自动重试计数 + 条目状态机不变量）。 */
export function isEntryCoherent(
  value: Record<string, unknown>,
  fields: NarrowedEntryFields,
  observationCount: number,
): boolean {
  if (!observationCountMatchesState(fields.phase, fields.attempts, observationCount)) {
    return false;
  }
  return parseEntryState(value, fields.reason, fields.phase, fields.attempts);
}

/** 条目装配（纯函数）：身份面 + 标量面 + 观测载荷 → RetryEntry。 */
export function buildRetryEntry(
  period: ReportPeriod,
  key: string,
  identity: { startDay: string; endDay: string; route: RetryRouteSnapshot },
  fields: NarrowedEntryFields,
  payload: { attemptObservations: RetryAttemptObservation[]; usage: RetryUsageTotals },
): RetryEntry {
  return {
    period,
    key,
    startDay: identity.startDay,
    endDay: identity.endDay,
    route: identity.route,
    attempts: fields.attempts,
    maxAttempts: RETRY_MAX_ATTEMPTS,
    nextRetryAt: fields.nextRetryAt,
    terminal: fields.terminal,
    reason: fields.reason,
    cycleId: fields.cycleId,
    phase: fields.phase,
    attemptObservations: payload.attemptObservations,
    usage: payload.usage,
  };
}

export function parseEntry(period: ReportPeriod, key: string, value: unknown): RetryEntry | null {
  if (!isRecord(value)) return null;
  if (!hasExpectedEntryKeys(value)) return null;
  const identity = parseEntryIdentity(value, period, key);
  if (identity === null) return null;
  const fields = narrowEntryFields(value);
  if (fields === null) return null;
  const payload = parseEntryPayload(value);
  if (payload === null) return null;
  if (!isEntryCoherent(value, fields, payload.attemptObservations.length)) return null;
  return buildRetryEntry(period, key, identity, fields, payload);
}

function parseTerminalKeys(value: unknown): RetryLedgerDocument["terminalKeys"] {
  if (value === undefined) return undefined;
  if (!isRecord(value)) throw new Error("invalid retry ledger terminal keys");
  const parsed: Record<string, Record<string, string>> = {};
  for (const [period, bucket] of Object.entries(value)) {
    if (!isReportPeriod(period) || !isRecord(bucket)) {
      throw new Error("invalid retry ledger terminal key period");
    }
    for (const [key, code] of Object.entries(bucket)) {
      if (!key || !isStableCode(code)) throw new Error("invalid retry ledger terminal key");
      parsed[period] = { ...(parsed[period] ?? {}), [key]: code };
    }
  }
  return parsed as RetryLedgerDocument["terminalKeys"];
}

/** 文档外壳键集合：terminalKeys 有无两形态（键多/键缺一律拒）。 */
export function hasExpectedDocumentKeys(value: Record<string, unknown>): boolean {
  const expectedKeys = Object.hasOwn(value, "terminalKeys")
    ? ["schema", "records", "terminalKeys"]
    : ["schema", "records"];
  return hasExactKeys(value, expectedKeys);
}

/** 单个 period 桶解析（key 不得含路径分隔符；条目须全量合法）。 */
export function parseRetryPeriodBucket(
  period: ReportPeriod,
  rawPeriod: unknown,
): Record<string, RetryEntry> {
  if (!isRecord(rawPeriod)) throw new Error("invalid retry ledger period");
  const bucket: Record<string, RetryEntry> = {};
  for (const [key, rawEntry] of Object.entries(rawPeriod)) {
    if (!key || key.includes("/") || key.includes("\\")) {
      throw new Error("invalid retry ledger key");
    }
    const entry = parseEntry(period, key, rawEntry);
    if (entry === null) throw new Error("invalid retry ledger entry");
    bucket[key] = entry;
  }
  return bucket;
}

/** 未知 period 拒绝（须在全部条目校验之后——判词顺序即错误优先级）。 */
export function assertKnownPeriodsOnly(raw: Record<string, unknown>): void {
  for (const period of Object.keys(raw)) {
    if (!isReportPeriod(period)) {
      throw new Error("unknown retry ledger period");
    }
  }
}

export function parseRetryRecords(raw: Record<string, unknown>): RetryRecords {
  const records: RetryRecords = {};
  for (const period of PERIODS) {
    const rawPeriod = raw[period];
    if (rawPeriod === undefined) continue;
    records[period] = parseRetryPeriodBucket(period, rawPeriod);
  }
  assertKnownPeriodsOnly(raw);
  return records;
}

export function parseDocument(value: unknown): RetryLedgerDocument {
  if (!isRecord(value)) {
    throw new Error("invalid retry ledger document");
  }
  if (!hasExpectedDocumentKeys(value)) {
    throw new Error("invalid retry ledger document");
  }
  if (value.schema !== RETRY_LEDGER_SCHEMA || !isRecord(value.records)) {
    throw new Error("invalid retry ledger schema");
  }
  const terminalKeys = parseTerminalKeys(value.terminalKeys);
  const records = parseRetryRecords(value.records);
  return {
    schema: RETRY_LEDGER_SCHEMA,
    records,
    ...(terminalKeys === undefined ? {} : { terminalKeys }),
  };
}

function cloneEntry(entry: RetryEntry): RetryEntry {
  return {
    ...entry,
    route:
      entry.route.reasoningEffort === undefined
        ? { provider: entry.route.provider, model: entry.route.model }
        : { ...entry.route },
    reason: entry.reason === null ? null : { ...entry.reason },
    attemptObservations: entry.attemptObservations.map((observation) => ({
      ...observation,
      tokens: { ...observation.tokens },
    })),
    usage: { ...entry.usage },
  };
}

function cloneTerminalKeys(
  terminalKeys: RetryLedgerDocument["terminalKeys"],
): RetryLedgerDocument["terminalKeys"] {
  if (terminalKeys === undefined) return undefined;
  const clone: Record<string, Record<string, string>> = {};
  for (const period of PERIODS) {
    const bucket = terminalKeys[period];
    if (bucket === undefined) continue;
    clone[period] = { ...bucket };
  }
  return clone as RetryLedgerDocument["terminalKeys"];
}

function cloneDocument(document: RetryLedgerDocument): RetryLedgerDocument {
  const records: RetryRecords = {};
  for (const period of PERIODS) {
    const bucket = document.records[period];
    if (bucket === undefined) continue;
    records[period] = Object.fromEntries(
      Object.entries(bucket).map(([key, entry]) => [key, cloneEntry(entry)]),
    );
  }
  const terminalKeys = cloneTerminalKeys(document.terminalKeys);
  return {
    schema: RETRY_LEDGER_SCHEMA,
    records,
    ...(terminalKeys === undefined ? {} : { terminalKeys }),
  };
}

/** 记录 terminal 墓碑并按 key 升序全量保留，确保序列化稳定且终态 key 不复活。 */
function rememberTerminalKey(
  document: RetryLedgerDocument,
  period: ReportPeriod,
  key: string,
  reason: RetryTerminalReason | null,
): void {
  const terminalKeys = document.terminalKeys ?? {};
  const bucket = { ...(terminalKeys[period] ?? {}) };
  bucket[key] = reason?.code ?? "terminal";
  terminalKeys[period] = Object.fromEntries(
    Object.keys(bucket)
      .sort()
      .map((entryKey) => [entryKey, bucket[entryKey]!] as const),
  );
  document.terminalKeys = terminalKeys;
}

function isTerminalKey(document: RetryLedgerDocument, period: ReportPeriod, key: string): boolean {
  return document.terminalKeys?.[period]?.[key] !== undefined;
}

/** reconcile/clear 命中即视为该 key 已闭环，墓碑随之失效。 */
function forgetTerminalKey(document: RetryLedgerDocument, period: ReportPeriod, key: string): void {
  const bucket = document.terminalKeys?.[period];
  if (bucket === undefined || bucket[key] === undefined) return;
  const next = { ...bucket };
  delete next[key];
  if (Object.keys(next).length === 0) {
    const terminalKeys = { ...document.terminalKeys };
    delete terminalKeys[period];
    document.terminalKeys =
      Object.keys(terminalKeys).length === 0
        ? undefined
        : (terminalKeys as RetryLedgerDocument["terminalKeys"]);
    return;
  }
  document.terminalKeys = { ...document.terminalKeys, [period]: next };
}

function pruneTerminalEntries(document: RetryLedgerDocument): RetryLedgerDocument {
  const next = cloneDocument(document);
  for (const period of PERIODS) {
    const bucket = next.records[period];
    if (bucket === undefined) continue;
    const terminalKeys = Object.keys(bucket)
      .filter((key) => bucket[key]!.terminal)
      .sort();
    // 裁掉的 terminal 记录留墓碑：key 仍属「已终态」，不得自动重开 cycle。
    for (const key of terminalKeys.slice(0, -1)) {
      rememberTerminalKey(next, period, key, bucket[key]!.reason);
      delete bucket[key];
    }
  }
  return next;
}

function flatten(document: RetryLedgerDocument): RetryEntry[] {
  const entries: RetryEntry[] = [];
  for (const period of PERIODS) {
    const bucket = document.records[period];
    if (bucket === undefined) continue;
    for (const key of Object.keys(bucket).sort()) entries.push(cloneEntry(bucket[key]!));
  }
  return entries;
}

function emptyDocument(): RetryLedgerDocument {
  return { schema: RETRY_LEDGER_SCHEMA, records: {} };
}

function serializeDocument(document: RetryLedgerDocument): string {
  const pruned = pruneTerminalEntries(document);
  const terminalKeys = cloneTerminalKeys(pruned.terminalKeys);
  const payload: RetryLedgerDocument =
    terminalKeys === undefined
      ? { schema: RETRY_LEDGER_SCHEMA, records: pruned.records }
      : { schema: RETRY_LEDGER_SCHEMA, records: pruned.records, terminalKeys };
  return JSON.stringify(payload);
}

function entryAt(
  document: RetryLedgerDocument,
  period: ReportPeriod,
  key: string,
): RetryEntry | undefined {
  const entry = document.records[period]?.[key];
  return entry === undefined ? undefined : cloneEntry(entry);
}

function setEntry(document: RetryLedgerDocument, entry: RetryEntry): void {
  const checked = parseEntry(entry.period, entry.key, entry);
  if (checked === null) throw new Error("invalid retry ledger entry");
  const bucket = document.records[entry.period] ?? {};
  bucket[entry.key] = checked;
  document.records[entry.period] = bucket;
}

function sameRoute(left: RetryRouteSnapshot, right: RetryRouteSnapshot): boolean {
  return (
    left.provider === right.provider &&
    left.model === right.model &&
    left.reasoningEffort === right.reasoningEffort
  );
}

function sameReason(left: RetryTerminalReason | null, right: RetryTerminalReason | null): boolean {
  if (left === null || right === null) return left === right;
  return left.code === right.code && left.kind === right.kind;
}

function sameTokens(left: RetryAttemptTokens, right: RetryAttemptTokens): boolean {
  return (
    left.inputTokens === right.inputTokens &&
    left.outputTokens === right.outputTokens &&
    left.reasoningTokens === right.reasoningTokens &&
    left.totalTokens === right.totalTokens &&
    left.cacheReadTokens === right.cacheReadTokens &&
    left.cacheWriteTokens === right.cacheWriteTokens
  );
}

/**
 * 单条观测等价。右侧缺席即不等价（调用方已先比长度，越界只可能来自越界读取）；
 * tokens 缺席视作全空，与历史实现的 `right?.[i]?.tokens ?? empty` 口径一致。
 */
function sameObservation(
  left: RetryAttemptObservation,
  right: RetryAttemptObservation | undefined,
): boolean {
  if (right === undefined) return false;
  return (
    left.attempt === right.attempt &&
    left.result === right.result &&
    left.code === right.code &&
    left.status === right.status &&
    left.durationMs === right.durationMs &&
    sameTokens(left.tokens, right.tokens)
  );
}

export function sameObservations(
  left: readonly RetryAttemptObservation[],
  right: readonly RetryAttemptObservation[],
): boolean {
  if (left.length !== right.length) return false;
  return left.every((observation, index) => sameObservation(observation, right[index]));
}

function sameUsage(left: RetryUsageTotals, right: RetryUsageTotals): boolean {
  return sameTokens(left, right) && left.durationMs === right.durationMs;
}

/** 条目窗口身份等价（period/key/窗口首末日）。 */
export function sameEntryWindow(left: RetryEntry, right: RetryEntry): boolean {
  return (
    left.period === right.period &&
    left.key === right.key &&
    left.startDay === right.startDay &&
    left.endDay === right.endDay
  );
}

/** 条目周期状态等价（尝试次数/排期/终态标记/相位）。 */
export function sameEntryCycle(left: RetryEntry, right: RetryEntry): boolean {
  return (
    left.attempts === right.attempts &&
    left.nextRetryAt === right.nextRetryAt &&
    left.terminal === right.terminal &&
    left.phase === right.phase
  );
}

export function claimMatchesCurrent(claim: RetryClaim, current: RetryEntry): boolean {
  const claimed = claim.entry;
  return (
    claim.cycleId === current.cycleId &&
    sameEntryWindow(claimed, current) &&
    sameEntryCycle(claimed, current) &&
    sameRoute(claimed.route, current.route) &&
    sameReason(claimed.reason, current.reason) &&
    sameObservations(claimed.attemptObservations, current.attemptObservations) &&
    sameUsage(claimed.usage, current.usage)
  );
}

function deleteEntry(document: RetryLedgerDocument, period: ReportPeriod, key: string): void {
  const bucket = document.records[period];
  if (bucket === undefined) return;
  delete bucket[key];
  if (Object.keys(bucket).length === 0) delete document.records[period];
}

async function syncDirectory(directory: string): Promise<void> {
  if (process.platform === "win32") return;
  let handle: Awaited<ReturnType<typeof open>> | undefined;
  try {
    handle = await open(directory, "r");
    await handle.sync();
  } catch (error: unknown) {
    if (
      ["EINVAL", "ENOTSUP", "EOPNOTSUPP", "ENOSYS", "EBADF", "EISDIR"].includes(
        errorCode(error) ?? "",
      )
    ) {
      return;
    }
    throw error;
  } finally {
    await handle?.close().catch(() => {});
  }
}

async function ensureReportsDirectory(root: string): Promise<string> {
  const reports = join(root, "reports");
  try {
    await mkdir(reports, { recursive: true, mode: 0o700 });
    await chmod(reports, 0o700);
    return reports;
  } catch {
    throw storageError();
  }
}

async function ensureCorruptMarker(reports: string): Promise<void> {
  const marker = join(reports, "retry-ledger.json.corrupt");
  let handle: Awaited<ReturnType<typeof open>>;
  try {
    handle = await open(marker, "wx", 0o600);
  } catch (error: unknown) {
    if (errorCode(error) === "EEXIST") return;
    throw storageError();
  }
  try {
    await handle.writeFile("retry-ledger-corrupt\n", "utf8");
    await handle.sync();
  } catch {
    throw storageError();
  } finally {
    await handle.close().catch(() => {});
  }
  try {
    await syncDirectory(reports);
  } catch {
    throw storageError();
  }
}

/** 不支持 hard-link 的文件系统错误码（退化为 exclusive copy 的前提）。 */
const HARDLINK_UNSUPPORTED = ["EPERM", "ENOTSUP", "EOPNOTSUPP", "ENOSYS", "EXDEV"];

/**
 * no-clobber 占位（返回 true = candidate 已占位；false = 已被占，换名重试）。
 * 同目录 hard-link 创建具备原子 no-clobber 语义；不支持时退化为 exclusive copy。
 * 其余错误上抛（证据不完整，不得继续隔离流程）。
 */
async function reserveNoClobber(file: string, candidate: string): Promise<boolean> {
  try {
    await link(file, candidate);
    return true;
  } catch (linkError: unknown) {
    if (errorCode(linkError) === "EEXIST") return false;
    if (!HARDLINK_UNSUPPORTED.includes(errorCode(linkError) ?? "")) throw linkError;
    try {
      await copyFile(file, candidate, constants.COPYFILE_EXCL);
      return true;
    } catch (copyError: unknown) {
      if (errorCode(copyError) === "EEXIST") return false;
      throw copyError;
    }
  }
}

async function moveToBackupNoClobber(file: string, backupBase: string): Promise<string> {
  for (let suffix = 0; ; suffix += 1) {
    const candidate = suffix === 0 ? backupBase : `${backupBase}-${suffix}`;
    if (!(await reserveNoClobber(file, candidate))) continue;
    await chmod(candidate, 0o600);
    await unlink(file);
    return candidate;
  }
}

function backupEntries(names: readonly string[], prefix: string): BackupEntry[] {
  const entries: BackupEntry[] = [];
  for (const name of names) {
    if (!name.startsWith(prefix)) continue;
    const match = /^(\d+)(?:-(\d+))?$/.exec(name.slice(prefix.length));
    if (match === null) continue;
    entries.push({
      name,
      timestamp: Number(match[1]),
      suffix: Number(match[2] ?? 0),
    });
  }
  return entries.sort(
    (left, right) => left.timestamp - right.timestamp || left.suffix - right.suffix,
  );
}

async function rotateBackups(
  reports: string,
  file: string,
  protectedBackup: string,
): Promise<void> {
  const prefix = "retry-ledger.json.bak-";
  const entries = backupEntries(await readdir(reports), prefix);
  const protectedPath = resolve(protectedBackup);
  const removable = entries.filter((entry) => resolve(join(reports, entry.name)) !== protectedPath);
  const removeCount = Math.max(0, removable.length - (CORRUPT_BACKUP_LIMIT - 1));
  for (const entry of removable.slice(0, removeCount)) {
    await unlink(join(reports, entry.name));
  }
  await syncDirectory(dirname(file));
}

async function quarantineCorrupt(root: string, file: string, now: number): Promise<never> {
  const reports = await ensureReportsDirectory(root);
  await ensureCorruptMarker(reports);
  try {
    const backup = await moveToBackupNoClobber(file, `${file}.bak-${now}`);
    await rotateBackups(reports, file, backup);
  } catch {
    throw storageError();
  }
  throw corruptError();
}

async function readDocumentUnlocked(root: string, now: number): Promise<RetryLedgerDocument> {
  const file = retryLedgerFile(root);
  const reports = dirname(file);
  if (existsSafe(join(reports, "retry-ledger.json.corrupt"))) throw corruptError();

  let raw: string;
  try {
    raw = await readFile(file, "utf8");
  } catch (error: unknown) {
    if (errorCode(error) === "ENOENT") return emptyDocument();
    throw storageError();
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    await quarantineCorrupt(root, file, now);
  }
  try {
    return pruneTerminalEntries(parseDocument(parsed));
  } catch {
    await quarantineCorrupt(root, file, now);
    throw corruptError();
  }
}

function existsSafe(path: string): boolean {
  try {
    return existsSync(path);
  } catch {
    return false;
  }
}

async function writeDocumentUnlocked(
  root: string,
  document: RetryLedgerDocument,
  renameFile: (from: string, to: string) => Promise<void>,
): Promise<void> {
  const file = retryLedgerFile(root);
  const reports = await ensureReportsDirectory(root);
  const temporary = `${file}.${process.pid}.${randomUUID()}.tmp`;
  let temporaryExists = false;
  try {
    const handle = await open(temporary, "wx", 0o600);
    temporaryExists = true;
    try {
      await handle.writeFile(serializeDocument(document), "utf8");
      await handle.sync();
    } finally {
      await handle.close();
    }
    await renameFile(temporary, file);
    temporaryExists = false;
    await chmod(file, 0o600);
    await syncDirectory(reports);
  } catch {
    if (temporaryExists) await unlink(temporary).catch(() => {});
    throw storageError();
  }
}

function withRootLock<T>(root: string, operation: () => Promise<T>): Promise<T> {
  const key = resolve(root);
  const previous = ledgerChains.get(key) ?? Promise.resolve();
  const run = previous.then(operation, operation);
  const tail = run.then(
    () => undefined,
    () => undefined,
  );
  ledgerChains.set(key, tail);
  return run.finally(() => {
    if (ledgerChains.get(key) === tail) ledgerChains.delete(key);
  });
}

function operationNow(options: RetryLedgerOptions, explicit: number | undefined): number {
  const value = explicit ?? options.now?.() ?? Date.now();
  if (!isFiniteTimestamp(value)) {
    throw new Error("retry ledger now must be a non-negative safe integer");
  }
  return value;
}

export function createRetryLedger(root: string, options: RetryLedgerOptions = {}): RetryLedgerPort {
  if (root.length === 0) throw new Error("retry ledger root must not be empty");
  const renameFile = options.renameFile ?? rename;
  const createCycleId = options.createCycleId ?? randomUUID;

  const read = (): Promise<RetryLedgerDocument> =>
    readDocumentUnlocked(root, operationNow(options, undefined));
  const write = (document: RetryLedgerDocument): Promise<void> =>
    writeDocumentUnlocked(root, document, renameFile);

  return {
    list: () => withRootLock(root, async () => flatten(await read())),

    listDue: (now, lastRun) =>
      withRootLock(root, async () => {
        const document = await read();
        return flatten(document).filter((entry) => {
          if (entry.terminal || (entry.phase !== "initial" && entry.phase !== "waiting")) {
            return false;
          }
          if (entry.nextRetryAt === null || entry.nextRetryAt > now) return false;
          const completed = lastRun[entry.period];
          return completed === undefined || entry.key > completed;
        });
      }),

    get: (period, key) =>
      withRootLock(root, async () => {
        const document = await read();
        if (!key || key.includes("/") || key.includes("\\")) return undefined;
        return entryAt(document, period, key);
      }),

    beginAttempt: (input, explicitNow) =>
      withRootLock(root, async () => {
        const now = operationNow(options, explicitNow);
        const document = await read();
        const current = entryAt(document, input.period, input.key);
        if (current === undefined && isTerminalKey(document, input.period, input.key)) {
          // 墓碑：该 key 曾终态失败，不得自动重开 cycle（只有 beginForce 可开新 cycle）。
          return null;
        }
        if (current !== undefined) {
          if (input.cycleId === undefined) return null;
          const claim = policyBeginAttempt(current, now, input.cycleId);
          if (claim === null) return null;
          setEntry(document, claim.entry);
          await write(document);
          return claim;
        }

        const initial = createInitialEntry(input, now, input.cycleId ?? createCycleId());
        const claim = policyBeginAttempt(initial, now, initial.cycleId);
        if (claim === null) throw new Error("retry ledger could not create initial claim");
        setEntry(document, claim.entry);
        await write(document);
        return claim;
      }),

    beginForce: (input, explicitNow) =>
      withRootLock(root, async () => {
        const now = operationNow(options, explicitNow);
        const document = await read();
        const current = entryAt(document, input.period, input.key);
        const cycleId = createCycleId();
        if (current?.cycleId === cycleId) throw new Error("retry ledger cycleId must be fresh");
        const forced = policyBeginForce(input, now, cycleId);
        // manual force 显式开新 cycle：墓碑随之失效。
        forgetTerminalKey(document, input.period, input.key);
        setEntry(document, forced);
        await write(document);
        return cloneEntry(forced);
      }),

    recordAttempt: (claim, observation, explicitNow) =>
      withRootLock(root, async () => {
        operationNow(options, explicitNow);
        const document = await read();
        const current = entryAt(document, claim.entry.period, claim.entry.key);
        if (current === undefined || !claimMatchesCurrent(claim, current)) return null;
        const next = addRetryObservation(claim, observation);
        setEntry(document, next.entry);
        await write(document);
        return { cycleId: next.cycleId, entry: cloneEntry(next.entry) };
      }),

    recordFailure: (claim, failure, explicitNow) =>
      withRootLock(root, async () => {
        const now = operationNow(options, explicitNow);
        const document = await read();
        const current = entryAt(document, claim.entry.period, claim.entry.key);
        if (current === undefined || !claimMatchesCurrent(claim, current)) return null;
        const next = policyRecordFailure(claim, failure, now);
        if (next === null) return null;
        setEntry(document, next);
        await write(document);
        return cloneEntry(next);
      }),

    recover: (explicitNow, keep) =>
      withRootLock(root, async () => {
        const now = operationNow(options, explicitNow);
        const document = await read();
        const held = new Set(
          (keep ?? [])
            .filter((item) => item.cycleId !== undefined)
            .map((item) => `${item.period}:${item.key}:${item.cycleId}`),
        );
        let changed = false;
        for (const period of PERIODS) {
          const bucket = document.records[period];
          if (bucket === undefined) continue;
          for (const [key, entry] of Object.entries(bucket)) {
            // storage-terminal 围栏内的 cycle 保持原 phase：不得回落 waiting 自动重跑。
            if (held.has(`${period}:${key}:${entry.cycleId}`)) continue;
            const recovered = policyRecover(entry, now);
            if (recovered !== entry) {
              bucket[key] = recovered;
              changed = true;
            }
          }
        }
        if (changed) await write(document);
        return flatten(document);
      }),

    clear: (claim) =>
      withRootLock(root, async () => {
        const document = await read();
        const current = entryAt(document, claim.entry.period, claim.entry.key);
        if (current === undefined || !claimMatchesCurrent(claim, current)) return false;
        deleteEntry(document, claim.entry.period, claim.entry.key);
        await write(document);
        return true;
      }),

    reconcile: (lastRun, indexed) =>
      withRootLock(root, async () => {
        const document = await read();
        const removed: RetryEntry[] = [];
        for (const entry of flatten(document)) {
          if (!shouldReconcileRetry(entry, lastRun, indexed)) continue;
          removed.push(entry);
          deleteEntry(document, entry.period, entry.key);
          forgetTerminalKey(document, entry.period, entry.key);
        }
        if (removed.length > 0) await write(document);
        return removed;
      }),
  };
}

/**
 * dsh-provider-usage — 报告重试纯状态机（#1010 B1）。
 *
 * 本文件只回答 cycle 内状态如何转移，不读取配置、不分配 cycleId、不做 I/O。
 * route 是 initial/force 时刻的不可变快照；调用方须用 cycleId 做 CAS，
 * 防止旧 cycle 的完成回调覆盖 force 创建的新 cycle。
 */

import type { ReportPeriod } from "../config/interface.ts";

export const RETRY_MAX_ATTEMPTS = 5 as const;
export const RETRY_BACKOFF_MS = [60_000, 120_000, 240_000, 480_000, 960_000] as const;

export type RetryFailureKind =
  "transient" | "empty-output" | "permanent" | "aborted" | "unknown" | "storage";

export type RetryPhase = "initial" | "waiting" | "in-flight" | "terminal";

export interface RetryRouteSnapshot {
  provider: string;
  model: string;
  reasoningEffort?: string;
}

export interface RetrySeed {
  period: ReportPeriod;
  key: string;
  startDay: string;
  endDay: string;
  route: RetryRouteSnapshot;
}

export interface RetryFailure {
  code: string;
  kind: RetryFailureKind;
}

export interface RetryTerminalReason {
  code: string;
  kind: RetryFailureKind;
}

/** 报告级 attempt 的安全 token 形状；不携带 provider 原文或推理文本。 */
export interface RetryAttemptTokens {
  inputTokens: number | null;
  outputTokens: number | null;
  reasoningTokens: number | null;
  totalTokens: number | null;
  cacheReadTokens: number | null;
  cacheWriteTokens: number | null;
}

/** 单次报告 outer attempt 的安全观测；attempt 从 1 开始。 */
export interface RetryAttemptObservation {
  attempt: number;
  result: "success" | "failure";
  code: string | null;
  status: "success" | "retry" | "terminal" | "aborted";
  durationMs: number | null;
  tokens: RetryAttemptTokens;
}

/** 周期累计事实；任一 attempt 缺失某字段时，该字段保持 null。 */
export interface RetryUsageTotals extends RetryAttemptTokens {
  durationMs: number | null;
}

export interface RetryEntry extends RetrySeed {
  attempts: number;
  maxAttempts: typeof RETRY_MAX_ATTEMPTS;
  nextRetryAt: number | null;
  terminal: boolean;
  reason: RetryTerminalReason | null;
  cycleId: string;
  phase: RetryPhase;
  attemptObservations: RetryAttemptObservation[];
  usage: RetryUsageTotals;
}

export interface RetryClaim {
  cycleId: string;
  entry: RetryEntry;
}

export interface RetryIndexKey {
  period: ReportPeriod;
  key: string;
  /** 成功 index 的事务 cycle；legacy/异 cycle 记录不能证明当前 claim。 */
  cycleId?: string;
}

function routeSnapshot(route: RetryRouteSnapshot): RetryRouteSnapshot {
  if (route.reasoningEffort === undefined) {
    return { provider: route.provider, model: route.model };
  }
  return { ...route };
}

function requireCycleId(cycleId: string): void {
  if (cycleId.length === 0) throw new Error("retry cycleId must not be empty");
}

const FAILURE_KINDS = new Set<RetryFailureKind>([
  "transient",
  "empty-output",
  "permanent",
  "aborted",
  "unknown",
  "storage",
]);

function requireFailure(failure: RetryFailure): void {
  if (!/^[a-z0-9][a-z0-9._:-]{0,63}$/.test(failure.code)) {
    throw new Error("retry failure code must be a stable identifier");
  }
  if (!FAILURE_KINDS.has(failure.kind)) {
    throw new Error("retry failure kind is invalid");
  }
}

function isRetryable(kind: RetryFailureKind): boolean {
  return kind === "transient" || kind === "empty-output";
}

const ATTEMPT_RESULTS = new Set<RetryAttemptObservation["result"]>(["success", "failure"]);
const ATTEMPT_STATUSES = new Set<RetryAttemptObservation["status"]>([
  "success",
  "retry",
  "terminal",
  "aborted",
]);

export function emptyRetryAttemptTokens(): RetryAttemptTokens {
  return {
    inputTokens: null,
    outputTokens: null,
    reasoningTokens: null,
    totalTokens: null,
    cacheReadTokens: null,
    cacheWriteTokens: null,
  };
}

export function emptyRetryUsage(): RetryUsageTotals {
  return { ...emptyRetryAttemptTokens(), durationMs: null };
}

function safeMetric(value: unknown): number | null {
  return typeof value === "number" && Number.isFinite(value) && value >= 0 ? value : null;
}

function validAttemptTokens(value: unknown): value is RetryAttemptTokens {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  const keys = [
    "inputTokens",
    "outputTokens",
    "reasoningTokens",
    "totalTokens",
    "cacheReadTokens",
    "cacheWriteTokens",
  ];
  if (Object.keys(record).length !== keys.length) return false;
  return keys.every((key) => record[key] === null || safeMetric(record[key]) !== null);
}

/** 单条 attempt 的字段形状约束：attempt 正整数、result/status 枚举、code 稳定码形态。 */
function requireObservationShape(observation: RetryAttemptObservation): void {
  if (!Number.isInteger(observation.attempt) || observation.attempt < 1) {
    throw new Error("retry observation attempt must be a positive integer");
  }
  if (!ATTEMPT_RESULTS.has(observation.result)) {
    throw new Error("retry observation result is invalid");
  }
  if (!ATTEMPT_STATUSES.has(observation.status)) {
    throw new Error("retry observation status is invalid");
  }
  if (observation.code !== null && !/^[a-z0-9][a-z0-9._:-]{0,63}$/.test(observation.code)) {
    throw new Error("retry observation code must be stable");
  }
}

/**
 * status 与 result 是否自洽：成功必为 status=success，失败必非 status=success
 * （失败可落在 retry/terminal/aborted）。等价于「success ⇔ status=success」。
 */
export function statusAgreesWithResult(observation: RetryAttemptObservation): boolean {
  if (observation.result === "success") return observation.status === "success";
  return observation.status !== "success";
}

/** 跨字段一致性约束：result⇔code 必填性、result⇔status、status⇔attempt 上限。 */
function requireObservationConsistency(observation: RetryAttemptObservation): void {
  if (observation.result === "success" && observation.code !== null) {
    throw new Error("successful retry observation must not have a failure code");
  }
  if (observation.result === "failure" && observation.code === null) {
    throw new Error("failed retry observation must have a failure code");
  }
  if (!statusAgreesWithResult(observation)) {
    throw new Error("retry observation result and status are inconsistent");
  }
  if (observation.status === "retry" && observation.attempt > RETRY_MAX_ATTEMPTS) {
    throw new Error("retry observation status and attempt are inconsistent");
  }
}

/** 度量载荷约束：tokens 六元组与 durationMs 形态。 */
function requireObservationMetrics(observation: RetryAttemptObservation): void {
  if (!validAttemptTokens(observation.tokens)) {
    throw new Error("retry observation tokens are invalid");
  }
  if (
    observation.durationMs !== null &&
    (typeof observation.durationMs !== "number" ||
      !Number.isFinite(observation.durationMs) ||
      observation.durationMs < 0)
  ) {
    throw new Error("retry observation duration is invalid");
  }
}

/** 单条 attempt 的全量校验（形状 + 一致性 + 度量，顺序即判词优先级）。 */
function requireObservation(observation: RetryAttemptObservation): void {
  requireObservationShape(observation);
  requireObservationConsistency(observation);
  requireObservationMetrics(observation);
}

function addNullable(left: number | null, right: number | null): number | null {
  return left === null || right === null ? null : left + right;
}

export function mergeRetryUsage(
  previous: RetryUsageTotals | null,
  tokens: RetryAttemptTokens,
  durationMs: number | null,
): RetryUsageTotals {
  if (previous === null) {
    return { ...tokens, durationMs };
  }
  return {
    inputTokens: addNullable(previous.inputTokens, tokens.inputTokens),
    outputTokens: addNullable(previous.outputTokens, tokens.outputTokens),
    reasoningTokens: addNullable(previous.reasoningTokens, tokens.reasoningTokens),
    totalTokens: addNullable(previous.totalTokens, tokens.totalTokens),
    cacheReadTokens: addNullable(previous.cacheReadTokens, tokens.cacheReadTokens),
    cacheWriteTokens: addNullable(previous.cacheWriteTokens, tokens.cacheWriteTokens),
    durationMs: addNullable(previous.durationMs, durationMs),
  };
}

export function usageFromRetryObservations(
  observations: readonly RetryAttemptObservation[],
): RetryUsageTotals {
  return (
    observations.reduce<RetryUsageTotals | null>(
      (total, current) => mergeRetryUsage(total, current.tokens, current.durationMs),
      null,
    ) ?? emptyRetryUsage()
  );
}

export function usageAfterRetryObservation(
  entry: RetryEntry,
  observation: RetryAttemptObservation,
): RetryUsageTotals {
  requireObservation(observation);
  const index = entry.attemptObservations.findIndex(
    (current) => current.attempt === observation.attempt,
  );
  const observations = [...entry.attemptObservations];
  if (index >= 0) observations[index] = observation;
  else observations.push(observation);
  return usageFromRetryObservations(observations);
}

/**
 * 覆盖既有 attempt 的前置条件：只允许覆盖最后一次 attempt，且只允许把「已判成功」
 * 的那次改判为失败（成功不可回退成成功，留给人工重跑的语义；其余改动须走重试 cycle）。
 */
function requireReplacementAllowed(
  claim: RetryClaim,
  observation: RetryAttemptObservation,
  index: number,
): void {
  if (index !== claim.entry.attemptObservations.length - 1) {
    throw new Error("retry observation replacement is not the latest attempt");
  }
  if (
    claim.entry.attemptObservations[index]?.result !== "success" ||
    observation.result !== "failure"
  ) {
    throw new Error("retry observation replacement must change a success attempt to failure");
  }
}

/**
 * 观测落位判定（纯函数）：返回命中槽位下标（<0 = 追加）。
 * 追加必须正好是 attempts+1（跳号/重号皆拒）；覆盖须过 requireReplacementAllowed。
 */
export function observationSlot(claim: RetryClaim, observation: RetryAttemptObservation): number {
  const index = claim.entry.attemptObservations.findIndex(
    (current) => current.attempt === observation.attempt,
  );
  if (index < 0) {
    if (observation.attempt !== claim.entry.attempts + 1) {
      throw new Error("retry observation attempt does not match claim");
    }
    return index;
  }
  requireReplacementAllowed(claim, observation, index);
  return index;
}

/** 落位应用（纯函数）：命中槽位覆盖，否则追加。 */
export function applyObservation(
  previous: readonly RetryAttemptObservation[],
  observation: RetryAttemptObservation,
  index: number,
): RetryAttemptObservation[] {
  const next = [...previous];
  if (index >= 0) next[index] = observation;
  else next.push(observation);
  return next;
}

export function addRetryObservation(
  claim: RetryClaim,
  observation: RetryAttemptObservation,
): RetryClaim {
  requireObservation(observation);
  if (claim.cycleId !== claim.entry.cycleId || claim.entry.phase !== "in-flight") {
    throw new Error("retry observation claim is not in-flight");
  }
  const attemptObservations = applyObservation(
    claim.entry.attemptObservations,
    observation,
    observationSlot(claim, observation),
  );
  return {
    cycleId: claim.cycleId,
    entry: {
      ...claim.entry,
      route: routeSnapshot(claim.entry.route),
      attemptObservations,
      usage: usageFromRetryObservations(attemptObservations),
    },
  };
}

export function createInitialEntry(seed: RetrySeed, now: number, cycleId: string): RetryEntry {
  requireCycleId(cycleId);
  return {
    period: seed.period,
    key: seed.key,
    startDay: seed.startDay,
    endDay: seed.endDay,
    route: routeSnapshot(seed.route),
    attempts: 0,
    maxAttempts: RETRY_MAX_ATTEMPTS,
    nextRetryAt: now,
    terminal: false,
    reason: null,
    cycleId,
    phase: "initial",
    attemptObservations: [],
    usage: emptyRetryUsage(),
  };
}

export function beginAttempt(
  entry: RetryEntry,
  now: number,
  expectedCycleId: string = entry.cycleId,
): RetryClaim | null {
  if (entry.cycleId !== expectedCycleId || entry.terminal || entry.phase === "in-flight") {
    return null;
  }
  if (entry.phase === "waiting" && entry.nextRetryAt !== null && now < entry.nextRetryAt) {
    return null;
  }
  const next: RetryEntry = {
    ...entry,
    route: routeSnapshot(entry.route),
    nextRetryAt: null,
    phase: "in-flight",
  };
  return { cycleId: entry.cycleId, entry: next };
}

export function recordFailure(
  claim: RetryClaim,
  failure: RetryFailure,
  now: number,
): RetryEntry | null {
  requireFailure(failure);
  if (claim.cycleId !== claim.entry.cycleId || claim.entry.phase !== "in-flight") return null;

  if (!isRetryable(failure.kind) || claim.entry.attempts >= RETRY_MAX_ATTEMPTS) {
    return {
      ...claim.entry,
      route: routeSnapshot(claim.entry.route),
      nextRetryAt: null,
      terminal: true,
      reason: { code: failure.code, kind: failure.kind },
      phase: "terminal",
    };
  }

  const attempts = claim.entry.attempts + 1;
  return {
    ...claim.entry,
    route: routeSnapshot(claim.entry.route),
    attempts,
    nextRetryAt: now + RETRY_BACKOFF_MS[attempts - 1]!,
    terminal: false,
    reason: null,
    phase: "waiting",
  };
}

export function beginForce(seed: RetrySeed, now: number, cycleId: string): RetryEntry {
  requireCycleId(cycleId);
  return {
    period: seed.period,
    key: seed.key,
    startDay: seed.startDay,
    endDay: seed.endDay,
    route: routeSnapshot(seed.route),
    attempts: 0,
    maxAttempts: RETRY_MAX_ATTEMPTS,
    nextRetryAt: now,
    terminal: false,
    reason: null,
    cycleId,
    phase: "waiting",
    attemptObservations: [],
    usage: emptyRetryUsage(),
  };
}

export function recover(entry: RetryEntry, now: number): RetryEntry {
  if (entry.phase !== "initial" && entry.phase !== "in-flight") return entry;
  return {
    ...entry,
    route: routeSnapshot(entry.route),
    nextRetryAt: now,
    terminal: false,
    reason: null,
    phase: "waiting",
  };
}

export function shouldReconcileRetry(
  entry: RetryEntry,
  lastRun: Partial<Record<ReportPeriod, string>>,
  indexed: readonly RetryIndexKey[],
): boolean {
  const completed = lastRun[entry.period];
  if (completed !== undefined && entry.key <= completed) return true;
  return indexed.some((item) => item.period === entry.period && item.key === entry.key);
}

/**
 * dsh-provider-usage — server/schedule 域：报告调度器。
 *
 * 组合根提供 historyRoot-scoped coordinator 后，启动顺序固定为
 * recover → lastRun/index reconciliation → 注册 interval → 首轮 tick。
 * ready 之前 tick 直接返回；recovery/storage 失败保持 fail-closed。
 */

import { randomUUID } from "node:crypto";
import { mkdir, readFile, rename, unlink, writeFile } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import type { ReportConfig, ReportPeriod } from "../config/interface.ts";
import { pendingReports, type DueReport } from "./due.ts";
import { readLastRun, ensureLastRunMigrated, updateLastRun } from "./store.ts";
import type { ScheduleIndexParser } from "./deps.ts";
import type {
  RetryAttemptObservation,
  RetryClaim,
  RetryEntry,
  RetryFailure,
  RetryIndexKey,
  RetrySeed,
} from "./retry-policy.ts";

type RetryAttemptInput = RetrySeed & { cycleId?: string };

interface RetryLedgerPort {
  list(): Promise<RetryEntry[]>;
  listDue(now: number, lastRun: Partial<Record<ReportPeriod, string>>): Promise<RetryEntry[]>;
  get(period: ReportPeriod, key: string): Promise<RetryEntry | undefined>;
  beginAttempt(input: RetryAttemptInput, now?: number): Promise<RetryClaim | null>;
  beginForce(input: RetrySeed, now?: number): Promise<RetryEntry>;
  recordAttempt(
    claim: RetryClaim,
    observation: RetryAttemptObservation,
    now?: number,
  ): Promise<RetryClaim | null>;
  recordFailure(claim: RetryClaim, failure: RetryFailure, now?: number): Promise<RetryEntry | null>;
  /** keep 中的 cycle 保持原 phase（storage-terminal fail-closed），不回落 waiting。 */
  recover(now?: number, keep?: readonly RetryIndexKey[]): Promise<RetryEntry[]>;
  clear(claim: RetryClaim): Promise<boolean>;
  reconcile(
    lastRun: Partial<Record<ReportPeriod, string>>,
    indexed: readonly RetryIndexKey[],
  ): Promise<RetryEntry[]>;
}

export interface ReportSchedulerOptions {
  /** 存储根（historyRoot）。 */
  root: string;
  /** 当前配置（updateConfig 热更新）。 */
  config: ReportConfig;
  /** 到期回调（提交到任务队列，非阻塞）。 */
  onDue: (due: DueReport) => Promise<void>;
  /** 注入时钟（测试）。 */
  now?: () => number;
  /** tick 间隔（默认 60000；测试可缩短）。 */
  tickMs?: number;
  /** 诊断出口。 */
  warn?: (msg: string) => void;
  /** 启动校准的 index 解析端口。 */
  parseIndex?: ScheduleIndexParser;
  /** 组合根状态协调器；存在时启用 recovery/ready 与单锁状态面。 */
  coordinator?: ReportStateCoordinator;
  /** 读取已成功 report/index 的 key，供 reconciliation 使用。 */
  listIndexed?: () => Promise<RetryIndexKey[]>;
}

/** 到期项的账本索引键（period:key）。 */
export function dueReportKey(due: Pick<DueReport, "period" | "key">): string {
  return `${due.period}:${due.key}`;
}

/** 账本条目降为到期项（终态过滤在合并侧做，此处不预判）。 */
export function dueReportOf(entry: RetryEntry): DueReport {
  return { period: entry.period, key: entry.key, startDay: entry.startDay, endDay: entry.endDay };
}

/**
 * 到期集合合并（纯函数）：
 * - 配置候选中，账本里**没有**对应条目的直接提交（尚未进入重试账本的首次窗口）；
 * - 账本 listDue 命中的非终态条目一律补提（已认领但未闭环的窗口不得漏跑）；
 * - 同键以先到者占位（Map 保持插入序，与历史实现的提交顺序一致）。
 */
export function mergeDueReports(
  current: readonly DueReport[],
  entries: readonly RetryEntry[],
  due: readonly RetryEntry[],
): DueReport[] {
  const byKey = new Map<string, RetryEntry>();
  for (const entry of entries) byKey.set(dueReportKey(entry), entry);
  const dueKeys = new Set<string>();
  for (const entry of due) dueKeys.add(dueReportKey(entry));
  const merged = new Map<string, DueReport>();
  for (const candidate of current) {
    const key = dueReportKey(candidate);
    if (byKey.get(key) === undefined || dueKeys.has(key)) merged.set(key, candidate);
  }
  for (const entry of due) {
    if (entry.terminal) continue;
    merged.set(dueReportKey(entry), dueReportOf(entry));
  }
  return [...merged.values()];
}

/** ledger 口径的到期集合：reconcile 后重算候选，再与账本非终态到期项合并。 */
async function collectLedgerDue(
  coordinator: ReportStateCoordinator,
  config: ReportConfig,
  now: () => number,
  lastRun: Partial<Record<ReportPeriod, string>>,
  listIndexed: (() => Promise<RetryIndexKey[]>) | undefined,
): Promise<DueReport[]> {
  const indexed = listIndexed === undefined ? [] : await listIndexed();
  await coordinator.reconcile(lastRun, indexed);
  const effectiveLastRun = await coordinator.readLastRun();
  const current = pendingReports(config, now(), effectiveLastRun);
  const entries = await coordinator.list();
  const due = await coordinator.listDue(now(), effectiveLastRun);
  return mergeDueReports(current, entries, due);
}

function diagnosticCode(error: unknown, fallback: string): string {
  if (typeof error === "object" && error !== null) {
    const code = (error as { code?: unknown }).code;
    if (typeof code === "string" && /^[a-z0-9][a-z0-9._:-]{0,63}$/.test(code)) return code;
  }
  return fallback;
}

export class ReportScheduler {
  private config: ReportConfig;
  private timer: ReturnType<typeof setInterval> | null = null;
  private disposed = false;
  private ticking = false;
  private readyState = false;
  private recoveryError = false;
  private readonly root: string;
  private readonly onDue: (due: DueReport) => Promise<void>;
  private readonly now: () => number;
  private readonly tickMs: number;
  private readonly warn: (msg: string) => void;
  private readonly parseIndex?: ScheduleIndexParser;
  private readonly coordinator?: ReportStateCoordinator;
  private readonly listIndexed?: () => Promise<RetryIndexKey[]>;
  /** recovery/ready 完成信号；失败时 resolve 但不开放 tick。 */
  readonly ready: Promise<void>;

  private constructor(opts: ReportSchedulerOptions) {
    this.root = opts.root;
    this.config = opts.config;
    this.onDue = opts.onDue;
    this.now = opts.now ?? Date.now;
    this.tickMs = opts.tickMs ?? 60_000;
    this.parseIndex = opts.parseIndex;
    this.coordinator = opts.coordinator;
    this.listIndexed = opts.listIndexed;
    this.warn = opts.warn ?? ((msg: string) => console.warn(`[dsh-provider-usage] report: ${msg}`));
    if (this.coordinator === undefined) {
      this.readyState = true;
      this.armTimer();
    }
    this.ready = this.initialize();
  }

  static start(opts: ReportSchedulerOptions): ReportScheduler {
    return new ReportScheduler(opts);
  }

  private async initialize(): Promise<void> {
    if (this.disposed) return;
    if (this.coordinator === undefined) {
      try {
        await ensureLastRunMigrated(this.root, this.warn, this.parseIndex);
        // Legacy startup anchor: ensureLastRunMigrated(s.root, s.warn, s.parseIndex)
      } finally {
        if (!this.disposed) {
          this.readyState = true;
          this.armTimer();
          void this.tick();
        }
      }
      return;
    }

    try {
      await this.coordinator.recover(this.now());
      // Legacy index rows without cycleId are trusted only when no live ledger entry exists; current cycles still require exact cycleId fencing.
      const lastRun = await this.coordinator.readLastRun();
      const indexed = this.listIndexed === undefined ? [] : await this.listIndexed();
      await this.coordinator.reconcile(lastRun, indexed);
      if (this.disposed) return;
      this.readyState = true;
      this.armTimer();
      await this.tick();
    } catch (error: unknown) {
      this.recoveryError = true;
      this.warn(`报告调度恢复失败（${diagnosticCode(error, "storage")}）`);
    }
  }

  private armTimer(): void {
    if (this.disposed || this.timer !== null || !this.readyState) return;
    this.timer = setInterval(() => void this.tick(), this.tickMs);
    (this.timer as { unref?: () => void }).unref?.();
  }

  /** 热更新配置（下轮 tick 生效）。 */
  updateConfig(config: ReportConfig): void {
    this.config = config;
  }

  /** tick 前置闸门：已释放 / 正在 tick / 未 ready / 恢复失败——任一成立即跳过本轮。 */
  private blocked(): boolean {
    return this.disposed || this.ticking || !this.readyState || this.recoveryError;
  }

  /**
   * 本轮到期集合。coordinator 缺席时只认配置候选；存在时先 reconcile 再重算，
   * 并与账本里的非终态到期项合并（见 mergeDueReports）。
   */
  private async collectDue(): Promise<DueReport[]> {
    const coordinator = this.coordinator;
    const lastRun =
      coordinator === undefined ? await readLastRun(this.root) : await coordinator.readLastRun();
    const current = pendingReports(this.config, this.now(), lastRun);
    if (coordinator === undefined) return current;
    return collectLedgerDue(coordinator, this.config, this.now, lastRun, this.listIndexed);
  }

  /** 失败诊断：coordinator 缺席时给原始 message，在场时只给稳定错误码（不外泄原文）。 */
  private reportFailure(context: string, error: unknown): void {
    this.warn(
      this.coordinator === undefined
        ? `${context}：${error instanceof Error ? error.message : String(error)}`
        : `${context}（${diagnosticCode(error, "storage")}）`,
    );
  }

  /** 一轮检查：ready 前直接返回；合并当前候选与已有 ledger 的非终态到期项。 */
  async tick(): Promise<void> {
    if (this.blocked()) return;
    this.ticking = true;
    try {
      for (const due of await this.collectDue()) {
        try {
          await this.onDue(due);
        } catch (error: unknown) {
          this.reportFailure(`${due.period} ${due.key} 提交失败`, error);
        }
      }
    } catch (error: unknown) {
      this.reportFailure("tick 异常", error);
    } finally {
      this.ticking = false;
    }
  }

  /** 停止 tick；ready 前 dispose 也会阻止后续注册。 */
  dispose(): void {
    this.disposed = true;
    if (this.timer !== null) {
      clearInterval(this.timer);
      this.timer = null;
    }
  }
}

export interface ReportStateCommitInput {
  claim: RetryClaim;
  result: {
    meta: {
      period: ReportPeriod;
      key: string;
    };
  };
  /** executor 提供的 current-cycle 落盘/通知回调；校验 claim 后在根锁内执行。 */
  persist: () => Promise<void>;
}

export interface ReportStateIndexReconcileInput {
  period: ReportPeriod;
  key: string;
  /** true 仅当 report/index 已确认该窗口成功。 */
  indexed: boolean;
  /** 新 index 记录的完成 cycle；旧 index 缺失或与当前 ledger 不同均不得清账。 */
  cycleId?: string;
}

export interface ReportStateCoordinatorOptions {
  root: string;
  ledger: RetryLedgerPort;
  readLastRun?: (root: string) => Promise<Partial<Record<ReportPeriod, string>>>;
  updateLastRun?: (
    root: string,
    patch: (
      previous: Partial<Record<ReportPeriod, string>>,
    ) => Partial<Record<ReportPeriod, string>> | Promise<Partial<Record<ReportPeriod, string>>>,
  ) => Promise<void>;
  now?: () => number;
}

export interface ReportStateCoordinator extends RetryLedgerPort {
  readLastRun(): Promise<Partial<Record<ReportPeriod, string>>>;
  updateLastRun(
    patch: (
      previous: Partial<Record<ReportPeriod, string>>,
    ) => Partial<Record<ReportPeriod, string>> | Promise<Partial<Record<ReportPeriod, string>>>,
  ): Promise<void>;
  commitSuccess(input: ReportStateCommitInput): Promise<boolean>;
  /** 幂等补完半提交事务（不含 ledger recover 本身；启动由 recover 串联调用）。 */
  recoverFence(): Promise<RetryFenceDocument>;
  reconcileIndex(input: ReportStateIndexReconcileInput): Promise<boolean>;
  migrateLastRun(
    warn?: (message: string) => void,
    parseIndex?: ScheduleIndexParser,
  ): Promise<{
    changed: boolean;
    before: Partial<Record<ReportPeriod, string>>;
    after: Partial<Record<ReportPeriod, string>>;
  }>;
}

/**
 * 事务围栏（#1010 残余 E）：commit 顺序为 persist → 半提交 marker → lastRun →
 * ledger.clear。marker 让「产物已落盘但 lastRun/clear 未完成」的半提交状态在崩溃
 * 或 storage 失败后可被幂等识别并补完：既不回滚已推进的 lastRun，也不重跑模型。
 *
 * 形态为 reports/retry-fence.json（0600 原子写）：
 * - commits[]：本 cycle 已完成 persist，恢复时补写 lastRun 并清账；
 * - storageTerminals[]：storage 失败且 terminalize 写入失败，恢复时保持
 *   in-flight（fail-closed），不得回落 waiting 自动重跑。
 */
export interface RetryFenceMarker {
  period: ReportPeriod;
  key: string;
  cycleId: string;
}

interface RetryFenceDocument {
  schema: 1;
  commits: RetryFenceMarker[];
  storageTerminals: RetryFenceMarker[];
}

export function retryFenceFile(root: string): string {
  return join(root, "reports", "retry-fence.json");
}

function sameMarker(left: RetryFenceMarker, right: RetryFenceMarker): boolean {
  return left.period === right.period && left.key === right.key && left.cycleId === right.cycleId;
}

function upsertMarker(list: RetryFenceMarker[], marker: RetryFenceMarker): void {
  const index = list.findIndex((item) => sameMarker(item, marker));
  if (index < 0) list.push(marker);
  else list[index] = marker;
}

function emptyFence(): RetryFenceDocument {
  return { schema: 1, commits: [], storageTerminals: [] };
}

function parseFence(raw: string): RetryFenceDocument {
  const parsed: unknown = JSON.parse(raw);
  if (typeof parsed !== "object" || parsed === null) throw new Error("invalid retry fence");
  const record = parsed as Record<string, unknown>;
  if (record.schema !== 1) throw new Error("invalid retry fence schema");
  const readMarkers = (value: unknown): RetryFenceMarker[] => {
    if (!Array.isArray(value)) throw new Error("invalid retry fence markers");
    return value.map((item) => {
      if (typeof item !== "object" || item === null) throw new Error("invalid retry fence marker");
      const marker = item as Record<string, unknown>;
      if (
        typeof marker.period !== "string" ||
        typeof marker.key !== "string" ||
        typeof marker.cycleId !== "string"
      ) {
        throw new Error("invalid retry fence marker fields");
      }
      return {
        period: marker.period as ReportPeriod,
        key: marker.key,
        cycleId: marker.cycleId,
      };
    });
  };
  return {
    schema: 1,
    commits: readMarkers(record.commits),
    storageTerminals: readMarkers(record.storageTerminals),
  };
}

const chains = new Map<string, Promise<void>>();

function withRootLock<T>(root: string, operation: () => Promise<T>): Promise<T> {
  const key = resolve(root);
  const previous = chains.get(key) ?? Promise.resolve();
  const run = previous.then(operation, operation);
  const tail = run.then(
    () => undefined,
    () => undefined,
  );
  chains.set(key, tail);
  return run.finally(() => {
    if (chains.get(key) === tail) chains.delete(key);
  });
}

/** claim 所指条目的窗口身份等价。 */
export function sameClaimWindow(left: RetryClaim, right: RetryEntry): boolean {
  return (
    left.entry.period === right.period &&
    left.entry.key === right.key &&
    left.entry.startDay === right.startDay &&
    left.entry.endDay === right.endDay
  );
}

/** claim 所指条目的周期状态等价。 */
export function sameClaimCycle(left: RetryClaim, right: RetryEntry): boolean {
  return (
    left.entry.phase === right.phase &&
    left.entry.attempts === right.attempts &&
    left.entry.terminal === right.terminal &&
    left.entry.nextRetryAt === right.nextRetryAt
  );
}

/** claim 仍指向当前条目（cycle 围栏）：身份、周期状态与成本载荷全等。 */
function sameClaim(left: RetryClaim, right: RetryEntry | undefined): boolean {
  if (right === undefined) return false;
  return (
    left.cycleId === right.cycleId &&
    sameClaimWindow(left, right) &&
    sameClaimCycle(left, right) &&
    JSON.stringify(left.entry.attemptObservations) === JSON.stringify(right.attemptObservations) &&
    JSON.stringify(left.entry.usage) === JSON.stringify(right.usage)
  );
}

function isCurrentIndexFact(
  current: RetryEntry | undefined,
  indexed: Pick<RetryIndexKey, "cycleId">,
): boolean {
  if (current === undefined) return indexed.cycleId === undefined;
  return (
    indexed.cycleId !== undefined &&
    current.cycleId === indexed.cycleId &&
    !current.terminal &&
    (current.phase === "waiting" || current.phase === "in-flight")
  );
}

function monotonic(
  previous: Partial<Record<ReportPeriod, string>>,
  period: ReportPeriod,
  key: string,
): Partial<Record<ReportPeriod, string>> {
  const old = previous[period];
  return old === undefined || key > old ? { ...previous, [period]: key } : previous;
}

type ReportStateStorageCode = "report-state-storage" | "report-persist-failed";

class ReportStateStorageError extends Error {
  readonly code: ReportStateStorageCode;

  constructor(code: ReportStateStorageCode = "report-state-storage") {
    super(
      code === "report-persist-failed" ? "报告持久化失败" : "report state storage operation failed",
    );
    this.code = code;
    this.name = "ReportStateStorageError";
  }
}

/** 读围栏文档；缺失即空围栏；损坏 fail-closed（不静默当空）。 */
async function readFence(root: string): Promise<RetryFenceDocument> {
  let raw: string;
  try {
    raw = await readFile(retryFenceFile(root), "utf8");
  } catch (error: unknown) {
    if ((error as { code?: unknown }).code === "ENOENT") return emptyFence();
    throw new ReportStateStorageError();
  }
  try {
    return parseFence(raw);
  } catch {
    throw new ReportStateStorageError();
  }
}

/** 原子写围栏文档（0600 临时文件 → rename）；写失败即 storage 失败。 */
async function writeFence(root: string, document: RetryFenceDocument): Promise<void> {
  const file = retryFenceFile(root);
  const temporary = `${file}.${process.pid}.${randomUUID()}.tmp`;
  try {
    await mkdir(dirname(file), { recursive: true, mode: 0o700 });
    await writeFile(temporary, JSON.stringify(document), { mode: 0o600 });
    await rename(temporary, file);
  } catch {
    await unlink(temporary).catch(() => {});
    throw new ReportStateStorageError();
  }
}

/**
 * storage 终态落盘：先写 ledger 的 terminal 记录；写失败则落 storage-terminal
 * 围栏标记（durable），使 recover 不会把该 cycle 回落为 waiting 自动重跑。
 */
async function terminalize(
  root: string,
  ledger: RetryLedgerPort,
  claim: RetryClaim,
  now: number,
  code: ReportStateStorageCode = "report-state-storage",
): Promise<void> {
  try {
    await ledger.recordFailure(claim, { kind: "storage", code }, now);
    return;
  } catch {
    // 原始存储错误不越过包边界；改以围栏标记保持 fail-closed。
  }
  const marker: RetryFenceMarker = {
    period: claim.entry.period,
    key: claim.entry.key,
    cycleId: claim.cycleId,
  };
  const fence = await readFence(root).catch(() => emptyFence());
  upsertMarker(fence.storageTerminals, marker);
  await writeFence(root, fence);
}

/** 创建一个 historyRoot-scoped 状态协调器。 */
export function createReportStateCoordinator(
  options: ReportStateCoordinatorOptions,
): ReportStateCoordinator {
  const root = options.root;
  if (root.length === 0) throw new Error("report state coordinator root must not be empty");
  const ledger = options.ledger;
  const read = options.readLastRun ?? readLastRun;
  const write = options.updateLastRun ?? updateLastRun;
  const now = options.now ?? Date.now;
  const locked = <T>(operation: () => Promise<T>): Promise<T> => withRootLock(root, operation);

  /**
   * 补完半提交事务：产物已落盘、lastRun/clear 未完成的 cycle 在恢复时幂等收尾
   * （monotonic 推进 lastRun + CAS 清账）。旧 cycle 标记（force 已开新 cycle）与
   * 已终结记录一律丢弃，绝不让旧产物清掉新 cycle 的账。
   */
  const finishHalfCommits = async (fence: RetryFenceDocument): Promise<RetryFenceDocument> => {
    if (fence.commits.length === 0 && fence.storageTerminals.length === 0) return fence;
    const live = await ledger.list();
    let advanced = await read(root);
    for (const marker of fence.commits) {
      const entry = live.find(
        (item) =>
          item.period === marker.period &&
          item.key === marker.key &&
          item.cycleId === marker.cycleId,
      );
      if (entry === undefined || entry.terminal) continue;
      advanced = monotonic(advanced, marker.period, marker.key);
      await write(root, () => advanced);
      await ledger.clear({ cycleId: marker.cycleId, entry });
    }
    // storage-terminal 标记：记录已不存在（clear 成功）即过期；仍在则保留 fail-closed。
    const next: RetryFenceDocument = {
      schema: 1,
      commits: [],
      storageTerminals: fence.storageTerminals.filter((marker) =>
        live.some(
          (item) =>
            item.period === marker.period &&
            item.key === marker.key &&
            item.cycleId === marker.cycleId,
        ),
      ),
    };
    await writeFence(root, next);
    return next;
  };

  return {
    list: () => locked(() => ledger.list()),
    listDue: (at, lastRun) => locked(() => ledger.listDue(at, lastRun)),
    get: (period, key) => locked(() => ledger.get(period, key)),
    beginAttempt: (input: RetryAttemptInput, at?: number) =>
      locked(() => ledger.beginAttempt(input, at ?? now())),
    beginForce: (input: RetrySeed, at?: number) =>
      locked(() => ledger.beginForce(input, at ?? now())),
    recordAttempt: (claim: RetryClaim, observation: RetryAttemptObservation, at?: number) =>
      locked(() => ledger.recordAttempt(claim, observation, at ?? now())),
    recordFailure: (claim: RetryClaim, failure: RetryFailure, at?: number) =>
      locked(() => ledger.recordFailure(claim, failure, at ?? now())),
    // recover 前先补完半提交事务；storage-terminal 围栏内的 cycle 保持 in-flight，
    // 不回落 waiting 自动重跑（fail-closed：只有 manual force 才开新 cycle）。
    recover: (at?: number) =>
      locked(async () => {
        const stamp = at ?? now();
        const fence = await readFence(root);
        await finishHalfCommits(fence);
        return ledger.recover(stamp, fence.storageTerminals);
      }),
    recoverFence: () => locked(() => readFence(root).then(finishHalfCommits)),
    clear: (claim: RetryClaim) => locked(() => ledger.clear(claim)),
    reconcile: (lastRun, indexed) =>
      locked(async () => {
        const entries = await ledger.list();
        const byKey = new Map(entries.map((entry) => [`${entry.period}:${entry.key}`, entry]));
        const successful = indexed.filter((item) =>
          isCurrentIndexFact(byKey.get(`${item.period}:${item.key}`), item),
        );
        const observed = await read(root);
        const advanced = successful.reduce(
          (state, item) => monotonic(state, item.period, item.key),
          observed,
        );
        if (JSON.stringify(advanced) !== JSON.stringify(observed)) {
          try {
            await write(root, () => advanced);
          } catch {
            throw new ReportStateStorageError();
          }
        }
        return ledger.reconcile(advanced, successful);
      }),
    readLastRun: () => locked(() => read(root)),
    updateLastRun: (patch) => locked(() => write(root, patch)),
    commitSuccess: (input) =>
      locked(async () => {
        const current = await ledger.get(input.claim.entry.period, input.claim.entry.key);
        if (!sameClaim(input.claim, current)) return false;
        const marker: RetryFenceMarker = {
          period: input.result.meta.period,
          key: input.result.meta.key,
          cycleId: input.claim.cycleId,
        };
        try {
          await input.persist();
        } catch {
          await terminalize(root, ledger, input.claim, now(), "report-persist-failed");
          throw new ReportStateStorageError("report-persist-failed");
        }
        // 半提交标记先于 lastRun 落盘：其后任一步失败都可被恢复流程幂等补完，
        // 不会让「产物已写、lastRun/clear 未完成」被当作普通 storage 失败重跑。
        const fence = await readFence(root);
        upsertMarker(fence.commits, marker);
        await writeFence(root, fence);
        try {
          await write(root, (previous) =>
            monotonic(previous, input.result.meta.period, input.result.meta.key),
          );
        } catch {
          // 半提交已标记：交由恢复流程补完，不得写 storage terminal 覆盖已落盘产物。
          throw new ReportStateStorageError();
        }
        try {
          const cleared = await ledger.clear(input.claim);
          await writeFence(root, {
            ...fence,
            commits: fence.commits.filter((item) => !sameMarker(item, marker)),
          });
          return cleared;
        } catch {
          // 同上：clear 失败是可恢复的半提交，不是 storage 终态（不反向回滚 lastRun）。
          throw new ReportStateStorageError();
        }
      }),

    reconcileIndex: (input) =>
      locked(async () => {
        const current = await ledger.get(input.period, input.key);
        if (!input.indexed || !isCurrentIndexFact(current, input)) return false;
        const previous = await read(root);
        const previousKey = previous[input.period];
        if (previousKey === undefined || input.key > previousKey) {
          try {
            await write(root, (currentLastRun) =>
              monotonic(currentLastRun, input.period, input.key),
            );
          } catch {
            throw new ReportStateStorageError();
          }
        }
        if (current === undefined) return true;
        return ledger.clear({ cycleId: current.cycleId, entry: current });
      }),
    migrateLastRun: async (warn, parseIndex) => {
      // Schema migration remains store-owned; run it under the same root lock.
      return locked(() => ensureLastRunMigrated(root, warn, parseIndex));
    },
  };
}

/**
 * dsh-provider-usage — server/schedule 域：lastRun 持久化原语（#768 D2，
 * 由 domain2/common/last-run.ts 搬入，零行为变更）。
 *
 * per-root 临界区链唯一实现：读-改-写按 root 串行 + 写前重读全量快照，
 * 防多写方（保存配置 preset / 任务执行器推进）交错 lost-update。调度与执行
 * 经本域 interface.ts 门面消费同一原语（D2 前在 domain2/common，
 * 叶层与 domain2/schedule 构成值环；D2 后归属明确，环消失）。
 */
import { readFile, writeFile, rename, mkdir } from "node:fs/promises";
import { join } from "node:path";
import type { ReportPeriod } from "../config/interface.ts";
import {
  alignLastRun,
  deriveLastRun,
  LAST_RUN_SCHEMA,
  type LastRunRecord,
} from "../shared/interface.ts";
import type { ScheduleIndexParser } from "./deps.ts";

/** lastRun 持久化文件。 */
function lastRunFile(root: string): string {
  return join(root, "reports", "last-run.json");
}

/** 读 lastRun（缺失/损坏返回空表）。导出供手动生成路由读改写复用。 */
export async function readLastRun(root: string): Promise<Partial<Record<ReportPeriod, string>>> {
  try {
    const raw = await readFile(lastRunFile(root), "utf8");
    const parsed = JSON.parse(raw) as Record<string, unknown>;
    const out: Partial<Record<ReportPeriod, string>> = {};
    for (const p of ["daily", "weekly", "monthly"] as const) {
      if (typeof parsed[p] === "string") out[p] = parsed[p];
    }
    return out;
  } catch {
    return {};
  }
}

/** 原子写 lastRun（tmp+rename，0600；带 schema 版本）。 */
export async function writeLastRun(
  root: string,
  state: Partial<Record<ReportPeriod, string>>,
): Promise<void> {
  const file = lastRunFile(root);
  await mkdir(join(root, "reports"), { recursive: true });
  const tmp = `${file}.${Date.now()}.tmp`;
  await writeFile(
    tmp,
    JSON.stringify({ ...state, schema: LAST_RUN_SCHEMA, updatedAt: Date.now() }),
    { mode: 0o600 },
  );
  await rename(tmp, file);
}

/**
 * 读 lastRun 原始全量（不应用 daily/weekly/monthly 白名单投影）——临界区写前重读
 * 专用：投影会静默丢弃非白名单键，round-trip 即 lost-update 的读取投影变体。
 */
async function readLastRunRaw(root: string): Promise<Record<string, unknown>> {
  try {
    const parsed: unknown = JSON.parse(await readFile(lastRunFile(root), "utf8"));
    return parsed !== null && typeof parsed === "object" && !Array.isArray(parsed)
      ? (parsed as Record<string, unknown>)
      : {};
  } catch {
    return {};
  }
}

const lastRunChainByRoot = new Map<string, Promise<void>>();

/**
 * lastRun 单一临界区：读-改-写按 root 串行（per-root promise 链）+ 写前重读。
 * 所有 lastRun 的 read-modify-write 统一收敛到本函数——patch 只在临界区内、基于
 * 链上最新文件快照计算；同一 root 的更新按提交序串行落盘。
 */
export function updateLastRun(
  root: string,
  // 返回类型必须容纳 Promise：patch 允许实现成 async（用于模拟读-改-写之间的交错窗），
  // 下面 await 它的结果。只声明同步形态属「签名撒谎」——await 非 Promise 不会报错也不会
  // 等待，一旦有人照着类型写同步实现并依赖这里真的等了，就是静默的时序 bug（#764 命中）。
  patch: (
    prev: Partial<Record<ReportPeriod, string>>,
  ) => Partial<Record<ReportPeriod, string>> | Promise<Partial<Record<ReportPeriod, string>>>,
): Promise<void> {
  const prev = lastRunChainByRoot.get(root) ?? Promise.resolve();
  const run = async (): Promise<void> => {
    const cur = await readLastRunRaw(root);
    // await patch 结果：patch 允许挂起（async 形态模拟交错窗），不 await 会让
    // writeLastRun 收到未 resolve 的 Promise、spread 丢全部字段。
    await writeLastRun(root, await patch(cur as Partial<Record<ReportPeriod, string>>));
  };
  const next = prev.then(run, run);
  const tail = next.then(
    () => undefined,
    () => undefined,
  );
  lastRunChainByRoot.set(root, tail);
  return next;
}

/** 测试隔离钩子：返回指定 root 的临界区链尾（await 确定收敛）。 */
export function __lastRunChainForTests(root: string): Promise<void> | undefined {
  return lastRunChainByRoot.get(root);
}

/** lastRun 校准结果（三键齐备，键存在性为对外契约）。 */
interface LastRunCalibration {
  changed: boolean;
  before: Partial<Record<ReportPeriod, string>>;
  after: Partial<Record<ReportPeriod, string>>;
}

/** plain object 判定（类型谓词，承担当前收窄）。 */
function isRecordLike(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

/** lastRun 文档的 schema 版本；非对象或缺键视作 1（历史无版本文档）。 */
export function schemaVersionOf(parsed: unknown): number {
  return isRecordLike(parsed) && typeof parsed.schema === "number" ? parsed.schema : 1;
}

/** 校准输入事实源：schema 版本 + index 事实。缺任一 → 无事实（raw 为 null）。 */
interface LastRunCalibrationInput {
  schema: number;
  before: Partial<Record<ReportPeriod, string>>;
  records: LastRunRecord[];
}

/**
 * 校准决策（纯函数）：schema 旧 → 全量重算（deriveLastRun）；schema 新 → 温和对齐
 * （alignLastRun）。changed 判据与决策同一口径，落盘后仍可原样复算。
 */
export function calibrateLastRun(
  schema: number,
  previous: Partial<Record<ReportPeriod, string>>,
  records: LastRunRecord[],
): { after: Partial<Record<ReportPeriod, string>>; changed: boolean } {
  const after = schema < LAST_RUN_SCHEMA ? deriveLastRun(records) : alignLastRun(previous, records);
  return {
    after,
    changed: schema < LAST_RUN_SCHEMA || JSON.stringify(previous) !== JSON.stringify(after),
  };
}

/**
 * 采集校准事实：lastRun 原文缺失 → 无 lastRun 事实（facts 为 null）；
 * index.jsonl 缺失或解析端口缺席 → 有 lastRun、无 index 事实（records 为 null）。
 * 端口缺席与「无 index」同语义，不静默捏造校准值。
 */
async function collectLastRunCalibrationInput(
  root: string,
  parseIndex: ScheduleIndexParser | undefined,
): Promise<LastRunCalibrationInput | { before: Partial<Record<ReportPeriod, string>> } | null> {
  const raw = await readFile(lastRunFile(root), "utf8").catch(() => null);
  if (raw === null) return null;
  const before = await readLastRun(root);
  const indexRaw = await readFile(join(root, "reports", "index.jsonl"), "utf8").catch(() => null);
  if (indexRaw === null || parseIndex === undefined) return { before };
  return { schema: schemaVersionOf(JSON.parse(raw)), before, records: parseIndex(indexRaw) };
}

export function isLastRunCalibrationInput(
  facts: LastRunCalibrationInput | { before: Partial<Record<ReportPeriod, string>> },
): facts is LastRunCalibrationInput {
  return "records" in facts;
}

/**
 * 启动时 lastRun 一致性保证：schema 旧 → 全量重算（deriveLastRun）；
 * schema 新 → 温和对齐（alignLastRun）；无 index 视作无事实，不动 lastRun。
 *
 * index 解析经 ScheduleIndexParser 端口注入（C 波单向化：本文件不直引
 * 执行域门面，纯函数实现由组合根装配期经调度器透传；缺端口视同无事实，
 * 不动 lastRun——与“无 index”同语义，不静默捏造校准值）。
 */
export async function ensureLastRunMigrated(
  root: string,
  warn?: (msg: string) => void,
  parseIndex?: ScheduleIndexParser,
): Promise<LastRunCalibration> {
  const diag = warn ?? ((msg: string) => console.warn(`[dsh-provider-usage] report: ${msg}`));
  try {
    const facts = await collectLastRunCalibrationInput(root, parseIndex);
    if (facts === null) return { changed: false, before: {}, after: {} };
    if (!isLastRunCalibrationInput(facts)) {
      return { changed: false, before: facts.before, after: facts.before };
    }
    const { after, changed } = calibrateLastRun(facts.schema, facts.before, facts.records);
    if (!changed) return { changed, before: facts.before, after };
    const finalAfter = await commitLastRunCalibration(root, facts);
    const msg =
      `schema ${facts.schema}→${LAST_RUN_SCHEMA}：` +
      `${JSON.stringify(facts.before)} → ${JSON.stringify(finalAfter)}`;
    diag(`lastRun 已按 index 事实校准（${msg}）`);
    return { changed, before: facts.before, after: finalAfter };
  } catch (e: unknown) {
    diag(`lastRun 校准失败（保持原状）：${e instanceof Error ? e.message : String(e)}`);
    return { changed: false, before: {}, after: {} };
  }
}

/**
 * 唯一写面：校准落盘经 per-root 链（与 preset/执行器同链串行）。
 * 链内按最新快照重算（preset 同形）：链外预读定 changed，链内重算定落盘值。
 */
async function commitLastRunCalibration(
  root: string,
  input: LastRunCalibrationInput,
): Promise<Partial<Record<ReportPeriod, string>>> {
  let written: Partial<Record<ReportPeriod, string>> | undefined;
  await updateLastRun(root, (cur) => {
    const fresh =
      input.schema < LAST_RUN_SCHEMA
        ? deriveLastRun(input.records)
        : alignLastRun(cur, input.records);
    written = fresh;
    return fresh;
  });
  return written ?? calibrateLastRun(input.schema, input.before, input.records).after;
}

/**
 * dsh-provider-usage — 报告生成任务队列。
 *
 * 队列只负责串行、去重与 force 生命周期；retry claim/cycle 仍由 executor 在
 * 真正开始执行前通过 coordinator 获取。force 请求先 durable prepare，再进入
 * 队列；运行中的旧 cycle 不被改写，后续 force cycle 独立排队。
 */

import { randomUUID } from "node:crypto";
import type { ReportPeriod } from "../config/interface.ts";
import type { ReportMeta } from "../execute/interface.ts";

export type ReportTaskStatus = "queued" | "running" | "done" | "failed";

/** 任务输入（窗口 + force 标志；不携带 ledger/cycle 字段）。 */
export interface ReportTaskInput {
  period: ReportPeriod;
  key: string;
  startDay: string;
  endDay: string;
  force?: boolean;
}

/** 任务状态记录（对外可查）。 */
export interface ReportTask {
  id: string;
  period: ReportPeriod;
  key: string;
  startDay: string;
  endDay: string;
  force: boolean;
  status: ReportTaskStatus;
  createdAt: number;
  updatedAt: number;
  meta?: ReportMeta;
  reused?: boolean;
  /** 生产队列只保存稳定错误 code；旧无 retry seam 保留兼容文本。 */
  error?: string;
}

export interface ReportTaskResult {
  meta?: ReportMeta;
  reused?: boolean;
}

export interface ReportTaskQueueOptions {
  executor: (input: ReportTaskInput) => Promise<ReportTaskResult>;
  now?: () => number;
  warn?: (msg: string) => void;
  ttlMs?: number;
  maxTasks?: number;
  /** force=true 时先 durable prepare；成功后才接受任务。 */
  prepareForce?: (input: ReportTaskInput) => Promise<void>;
  /** 生产组合根开启稳定错误码；旧测试/兼容调用未开启时保留旧文本。 */
  sanitizeErrors?: boolean;
}

export interface ReportTaskSubmission {
  taskId: string;
  existing: boolean;
}

interface TaskRuntime {
  scheduled: boolean;
  running: boolean;
}

type ResolveSubmission = (value: ReportTaskSubmission) => void;
type RejectSubmission = (reason?: unknown) => void;

interface PendingForce {
  readonly key: string;
  readonly task: ReportTask;
  readonly input: ReportTaskInput;
  readonly submissionExisting: boolean;
  normalRequested: boolean;
  prepared: boolean;
  settled: boolean;
  readonly operation: Promise<ReportTaskSubmission>;
  readonly resolve: ResolveSubmission;
  readonly reject: RejectSubmission;
}

function taskKey(input: Pick<ReportTaskInput, "period" | "key">): string {
  return `${input.period}\u0000${input.key}`;
}

function stableErrorCode(error: unknown, fallback: string): string {
  if (typeof error === "object" && error !== null) {
    const value = (error as { code?: unknown; message?: unknown }).code;
    if (typeof value === "string" && /^[a-z0-9][a-z0-9._:-]{0,63}$/.test(value)) return value;
  }
  return fallback;
}

export class ReportTaskQueue {
  private readonly tasks = new Map<string, ReportTask>();
  private readonly runtimes = new Map<string, TaskRuntime>();
  private readonly pendingForces = new Map<string, PendingForce>();
  private readonly preparedForceTasks = new Set<string>();
  private tail: Promise<unknown> = Promise.resolve();
  /** 保留 force prepare+activate 的全局串行语义；reservation 只屏蔽普通 submit。 */
  private forceTail: Promise<unknown> = Promise.resolve();
  private readonly executor: (input: ReportTaskInput) => Promise<ReportTaskResult>;
  private readonly now: () => number;
  private readonly warn: (msg: string) => void;
  private readonly ttlMs: number;
  private readonly maxTasks: number;
  private readonly prepareForce?: (input: ReportTaskInput) => Promise<void>;
  private readonly sanitizeErrors: boolean;

  constructor(opts: ReportTaskQueueOptions) {
    this.executor = opts.executor;
    this.now = opts.now ?? Date.now;
    this.warn = opts.warn ?? ((msg: string) => console.warn(`[dsh-provider-usage] report: ${msg}`));
    this.ttlMs = opts.ttlMs ?? 600_000;
    this.maxTasks = opts.maxTasks ?? 50;
    this.prepareForce = opts.prepareForce;
    this.sanitizeErrors = opts.sanitizeErrors ?? false;
  }

  /**
   * 提交非 force 任务（同步兼容入口）。force=true 的生产路径应调用 submitForce；
   * 没有 prepareForce 时仍按旧测试语义执行，但不会伪造 durable force。
   */
  submit(input: ReportTaskInput): ReportTaskSubmission {
    return this.enqueue(input, input.force === true);
  }

  /** force 入口：同步登记 reservation，durable prepare 成功后才激活 task。 */
  submitForce(input: ReportTaskInput): Promise<ReportTaskSubmission> {
    const key = taskKey(input);
    const pending = this.pendingForces.get(key);
    if (pending !== undefined) return pending.operation;

    const queued = this.findQueued(input);
    if (queued !== undefined && queued.force && this.preparedForceTasks.has(queued.id)) {
      return Promise.resolve({ taskId: queued.id, existing: true });
    }

    const wasNormal = queued !== undefined && !queued.force;
    const task = queued ?? this.createTask(input, true);
    task.force = true;
    const reservation = this.createPendingForce(input, task, queued !== undefined, wasNormal);
    this.pendingForces.set(key, reservation);
    this.prune();

    if (this.prepareForce === undefined) {
      this.activateForce(reservation);
      return reservation.operation;
    }

    const operation = this.forceTail.then(async () => {
      try {
        await this.prepareForce?.(input);
        this.activateForce(reservation);
      } catch (error: unknown) {
        this.rejectForce(reservation, error);
      }
    });
    this.forceTail = operation.then(
      () => undefined,
      () => undefined,
    );
    return reservation.operation;
  }

  private enqueue(input: ReportTaskInput, force: boolean): ReportTaskSubmission {
    const pending = this.pendingForces.get(taskKey(input));
    if (pending !== undefined) {
      if (!force) pending.normalRequested = true;
      return { taskId: pending.task.id, existing: true };
    }

    for (const task of this.tasks.values()) {
      if (task.period !== input.period || task.key !== input.key) continue;
      if (task.status === "queued") {
        if (force) task.force = true;
        return { taskId: task.id, existing: true };
      }
      if (task.status === "running" && !force) {
        return { taskId: task.id, existing: true };
      }
      // running + force intentionally falls through to a later cycle.
    }

    const task = this.createTask(input, force);
    this.schedule(task);
    this.prune();
    return { taskId: task.id, existing: false };
  }

  private findQueued(input: ReportTaskInput): ReportTask | undefined {
    for (const task of this.tasks.values()) {
      if (task.period === input.period && task.key === input.key && task.status === "queued") {
        return task;
      }
    }
    return undefined;
  }

  private createTask(input: ReportTaskInput, force: boolean): ReportTask {
    const now = this.now();
    const task: ReportTask = {
      id: randomUUID(),
      period: input.period,
      key: input.key,
      startDay: input.startDay,
      endDay: input.endDay,
      force,
      status: "queued",
      createdAt: now,
      updatedAt: now,
    };
    this.tasks.set(task.id, task);
    this.runtimes.set(task.id, { scheduled: false, running: false });
    return task;
  }

  private createPendingForce(
    input: ReportTaskInput,
    task: ReportTask,
    submissionExisting: boolean,
    normalRequested: boolean,
  ): PendingForce {
    let resolveOperation!: ResolveSubmission;
    let rejectOperation!: RejectSubmission;
    const operation = new Promise<ReportTaskSubmission>((resolve, reject) => {
      resolveOperation = resolve;
      rejectOperation = reject;
    });
    return {
      key: taskKey(input),
      task,
      input,
      submissionExisting,
      normalRequested,
      prepared: false,
      settled: false,
      operation,
      resolve: resolveOperation,
      reject: rejectOperation,
    };
  }

  private activateForce(reservation: PendingForce): void {
    if (reservation.settled) return;
    if (this.pendingForces.get(reservation.key) !== reservation) return;
    reservation.prepared = true;
    this.pendingForces.delete(reservation.key);
    this.preparedForceTasks.add(reservation.task.id);
    if (reservation.task.status === "queued") this.schedule(reservation.task);
    reservation.settled = true;
    reservation.resolve({
      taskId: reservation.task.id,
      existing: reservation.submissionExisting,
    });
  }

  private rejectForce(reservation: PendingForce, error: unknown): void {
    if (reservation.settled) return;
    if (this.pendingForces.get(reservation.key) !== reservation) return;
    this.pendingForces.delete(reservation.key);
    this.preparedForceTasks.delete(reservation.task.id);
    reservation.settled = true;

    if (reservation.normalRequested) {
      // A normal submit was already accepted (or is single-flighting on this
      // reservation): run it without force so a failed prepare cannot strand it.
      reservation.task.force = false;
      if (reservation.task.status === "queued") this.schedule(reservation.task);
    } else {
      // No ordinary request depends on this placeholder. Keep the public task
      // terminal for status compatibility, but never leave a queued gate behind.
      reservation.task.status = "failed";
      reservation.task.error = this.sanitizeErrors
        ? stableErrorCode(error, "force-prepare-failed")
        : error instanceof Error
          ? error.message
          : String(error);
      reservation.task.updatedAt = this.now();
      this.prune();
    }
    reservation.reject(error);
  }

  get(taskId: string): ReportTask | undefined {
    return this.tasks.get(taskId);
  }

  private schedule(task: ReportTask): void {
    const runtime = this.runtimes.get(task.id);
    if (runtime === undefined || runtime.scheduled || runtime.running) return;
    runtime.scheduled = true;
    this.tail = this.tail.then(() => this.runScheduled(task)).catch(() => undefined);
  }

  private async runScheduled(task: ReportTask): Promise<void> {
    const runtime = this.runtimes.get(task.id);
    if (runtime === undefined) return;
    runtime.scheduled = false;
    if (task.status !== "queued") return;

    const pending = this.pendingForces.get(taskKey(task));
    if (pending?.task.id === task.id && !pending.prepared) {
      // Do not hold the global tail while this key waits for durable prepare.
      return;
    }

    runtime.running = true;
    try {
      await this.run(task);
    } finally {
      runtime.running = false;
    }
  }

  private async run(task: ReportTask): Promise<void> {
    task.status = "running";
    task.updatedAt = this.now();
    try {
      const result = await this.executor({
        period: task.period,
        key: task.key,
        startDay: task.startDay,
        endDay: task.endDay,
        force: task.force,
      });
      task.status = "done";
      task.meta = result.meta;
      task.reused = result.reused === true;
      task.updatedAt = this.now();
    } catch (error: unknown) {
      task.status = "failed";
      if (this.sanitizeErrors) {
        const code = stableErrorCode(error, "generation-failed");
        task.error = code;
        this.warn(`task ${task.period} ${task.key} 执行失败（${code}）`);
      } else {
        const message = error instanceof Error ? error.message : String(error);
        task.error = message;
        this.warn(`task ${task.period} ${task.key} 执行失败：${message}`);
      }
      task.updatedAt = this.now();
    }
  }

  private prune(): void {
    this.dropExpired();
    this.enforceCapacity();
  }

  /** 淘汰策略一：已结算且超出 TTL 的任务。 */
  private dropExpired(): void {
    const cutoff = this.now() - this.ttlMs;
    for (const [id, task] of this.tasks) {
      if (isSettled(task) && task.updatedAt < cutoff) this.forget(id);
    }
  }

  /**
   * 淘汰策略二：超容量时逐个挤掉最老的已结算任务。
   * 在跑的（queued/running）不可挤——容量超限且无可挤时保留现状，等其结算。
   */
  private enforceCapacity(): void {
    while (this.tasks.size > this.maxTasks) {
      const oldest = this.oldestSettledId();
      if (oldest === null) break;
      this.forget(oldest);
    }
  }

  /** 最老的已结算任务 id；无已结算任务返回 null。 */
  private oldestSettledId(): string | null {
    let oldest: string | null = null;
    let oldestAt = Number.POSITIVE_INFINITY;
    for (const [id, task] of this.tasks) {
      if (!isSettled(task)) continue;
      if (task.createdAt < oldestAt) {
        oldestAt = task.createdAt;
        oldest = id;
      }
    }
    return oldest;
  }

  /** 任务本体与两处旁挂表（runtime 句柄、force 预置任务）同步移除。 */
  private forget(id: string): void {
    this.tasks.delete(id);
    this.runtimes.delete(id);
    this.preparedForceTasks.delete(id);
  }
}

/** 已结算（不再占用执行槽、可被淘汰）的任务状态判定。 */
export function isSettled(task: Pick<ReportTask, "status">): boolean {
  return task.status === "done" || task.status === "failed";
}

/**
 * dsh-provider-usage — server/shared last-run 纯面叶子（#768 A波4）。
 *
 * LAST_RUN_SCHEMA / LastRunRecord / isClosedWindowRecord / deriveLastRun /
 * alignLastRun 的 canonical 落点（由 server/schedule/due.ts 纯面逐字下沉，
 * 零行为变更；updateLastRun 有状态临界区留 schedule 域不动）。
 * 共享层准入：无单一所有者（schedule 启动校准 + upgrade 迁移双消费）、
 * 零值进口域（仅值引 src/shared 日界 + type-only 引 ReportPeriod）、≥2 正当消费者。
 * 目录外经 server/shared/interface.ts 消费，旧址 server/schedule/due.ts 保留
 * re-export 门面（生产与测试同源，均经 shared 门面）。
 */
import { dayKey } from "../../shared/interface.ts";
import type { ReportPeriod } from "../config/interface.ts";

/** last-run.json schema 版本（v2 = daily 候选键语义统一为「已闭环窗口」）。 */
export const LAST_RUN_SCHEMA = 2;

/** 迁移/推导输入：index.jsonl 单条记录的最小字段（鸭子类型，避免与 runner 循环依赖）。 */
export interface LastRunRecord {
  period: ReportPeriod;
  key: string;
  generatedAt: number;
  endDay: string;
  ok: boolean;
}

/**
 * 「窗口已闭环」判定：生成时刻所在本地日 > 窗口结束日。
 * 纯字符串日期序（dayKey(generatedAt) > endDay），与 addDays/dayKey 同源构造：
 * - 旧语义 daily「当天」记录（发起日 = endDay 当天）恒不闭环（窗口未走完）；
 * - 新语义 daily「昨天」记录（发起日 = endDay+1）恒闭环；
 * - weekly/monthly 生成时刻天然晚于窗口结束。
 * 禁用时间戳 + 23:59:59 构造：Date.parse("…T23:59:59") 无时区按 UTC 解析，
 * UTC+8 下会把新语义闭环记录误判为未闭环（无限补跑）且 CI 时区盲区不可测。
 */
export function isClosedWindowRecord(r: LastRunRecord): boolean {
  return r.ok === true && dayKey(r.generatedAt) > r.endDay;
}

/**
 * 由 index.jsonl 事实推导 lastRun（迁移 + 长期一致性口径）：
 * 「lastRun = 各期最新已闭环窗口的键」——与读侧投影同构：index 是事实日志，
 * lastRun 是投影，任何时刻可重算（幂等、可重放、自动修复旧语义污染键）。
 * - 有闭环记录 → 取最晚键（已扣期语义不变：候选键 <= lastRun 即跳过）；
 * - 无闭环记录（从未生成 / index 清理过 / 旧语义「当天」污染）→ 不设键（恢复补跑，
 *   最多重生成最近一期，幂等安全）。
 */
export function deriveLastRun(records: LastRunRecord[]): Partial<Record<ReportPeriod, string>> {
  const out: Partial<Record<ReportPeriod, string>> = {};
  for (const period of ["daily", "weekly", "monthly"] as const) {
    let maxKey: string | undefined;
    for (const r of records) {
      if (r.period !== period || !isClosedWindowRecord(r)) continue;
      if (maxKey === undefined || r.key > maxKey) maxKey = r.key;
    }
    if (maxKey !== undefined) out[period] = maxKey;
  }
  return out;
}

/**
 * schema 已新（>=2）时的温和校准：仅「该期 index 存在已闭环记录」才把 lastRun
 * 对齐到最新闭环键（修旧语义污染/遮蔽事故的滞后与超前），否则保留原值——
 * 保护「首次启用预置扣期」键（preset 键在 index 中天然无对应记录，
 * 全量重算会删掉它导致首次启用被立即补跑）。
 */
export function alignLastRun(
  lastRun: Partial<Record<ReportPeriod, string>>,
  records: LastRunRecord[],
): Partial<Record<ReportPeriod, string>> {
  const out = { ...lastRun };
  for (const period of ["daily", "weekly", "monthly"] as const) {
    let maxKey: string | undefined;
    for (const r of records) {
      if (r.period !== period || !isClosedWindowRecord(r)) continue;
      if (maxKey === undefined || r.key > maxKey) maxKey = r.key;
    }
    if (maxKey !== undefined) out[period] = maxKey;
  }
  return out;
}

