        return () => `cycle-${(sequence += 1)}`;
      })(),
    );
    const coordinator = createReportStateCoordinator({ root, ledger, now: () => RETRY_NOW });
    let releaseCommit = (): void => undefined;
    let markCommitEntered = (): void => undefined;
