          period: "daily" as const,
          key: RETRY_DAY,
          startDay: RETRY_DAY,
          endDay: RETRY_DAY,
          provider: "generic-provider",
          model: "generic-model",
          generatedAt: RETRY_NOW + 2,
          durationMs: 1,
          ok: true,
        },
      };
      expect(
        await coordinator.commitSuccess({
