      expect(readFileSync(htmlFile, "utf8")).toContain("cycle-2 新正文");
      expect(readFileSync(htmlFile, "utf8")).not.toContain("报告正文");
      expect(JSON.parse(readFileSync(metaFile, "utf8"))).toMatchObject({
