};

const DEFAULT_SELECTED_MODEL: SelectedModelFixture = {
  id: "vendor-b::model",
  name: "Vendor B Model",
  reasoning: {
    efforts: [
      {
        id: "vendor::balanced",
        name: "Balanced",
        description: "Balanced description from DSH",
      },
      {
        id: "vendor::deep",
        name: "Deep",
        description: "Deep description from DSH",
