    fireEvent.change(view.getByLabelText("reportReasoningEffort"), { target: { value: "" } });
    expect(dirtyScopes(view)).toEqual(["dou-reportHead", "dou-reportSectionHead"]);
    fireEvent.click(view.getByRole("button", { name: "reportSave" }));
